(window.GIM_TS=window.GIM_TS||{})["Pesachim.8"]={"from":192,"a":[["\u0003המפריש פסחו ומת — לא יביאנו בנו אחריו לשם פסח\u0004 שכיון שמתו הבעלים בטל מתורת פסח \u0003אלא\u0004 יביאנו \u0003לשם שלמים.\u0004","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע שמע מינה\u0004 \u0005[למד ממנה]\u0006 מן המשנה האומרת שהמפריש נקבה לפסחו תרעה עד שתסתאב \u0003תלת\u0004 \u0005[שלושה]\u0006 דברים. \u0003שמע מינה\u0004 \u0005[למד ממנה]:\u0006 כי \u0003בעלי חיים נדחין\u0004 שדין זה שקרבן נדחה מלהיות ראוי להקרבה חל לא רק בקרבן שכבר נשחט, אלא גם בבהמה חיה שהוקדשה לקרבן שאינה ראויה לו. שנחלקו תנאים בנושא זה, ובמשנתנו ברור שאותה נקיבה שהוקדשה לפסח בעודה חיה — דחויה היא שהרי אינה קריבה שלמים אלא יפלו דמיה לנדבה.","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003דחוי מעיקרא\u0004 \u0005[מתחילה]\u0006 בעצם הקדשתו \u0003הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003דחוי,\u0004 שהרי בהמה זו מתחילתה לא היתה ראויה לפסח ואפשר היה לומר שאינה דחויה אלא תיקרב שלמים, שהרי לא היתה ראויה אלא לשלמים, ומתוך שאינה קריבה שלמים הריהי נחשבת כדחויה מעיקרה. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003יש דחוי\u0004 לא רק בגוף הקרבן עצמו אלא גם \u0003בדמים\u0004 של אותו קרבן, שהרי דמי אותה בהמה אין משתמשים בהם לשלמים אלא לצורך נדבה (ר\"ח).","במשנה נאמר שאם \u0003המפריש פסחו\u0004 ומת אל יביאנו בנו כפסח. בתוספתא \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המפריש את פסחו ומת, אם\u0004 היה \u0003בנו ממונה עמו\u0004 על אותו פסח \u0003יביאנו לשום פסח\u0004 שהוא כפסח שמת רק אחד ממנוייו שאינו נפסל כולו, אבל אם \u0003אין בנו ממונה עמו — יביאנו לשום שלמים לששה עשר\u0004 בניסן, ביום חול המועד של פסח. ומדייקים: \u0003לששה עשר — אין\u0004 \u0005[כן],\u0006 אבל \u0003לחמשה עשר\u0004 ביום החג עצמו — \u0003לא.\u0004 משמע ש\u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 תנא זה: \u0003נדרים ונדבות אין קריבין ביום טוב\u0004 אלא רק קרבנות שהם מחובת החג.","ונברר: \u0003דמית\u0004 \u0005[שמת]\u0006 \u0003האב אימת\u0004 \u0005[אימתי]?\u0006 \u0003אילימא דמית\u0004 \u0005[אם תאמר שמת]\u0006 האב \u0003קודם חצות\u0004 יום ארבעה עשר, כיצד אפשר להבין את ההמשך שאם היה \u0003בנו ממונה עמו — יביאנו לשום\u0004 (לשם) \u0003פסח,\u0004 אולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חלה אנינות,\u0004 אבילות מסויימת, \u0003עילויה\u0004 \u0005[עליו]\u0006 \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 עם מות אביו, והאונן אינו רשאי להקריב את הפסח!","\u0003אלא\u0004 יש לומר \u0003דמית\u0004 \u0005[שמת]\u0006 \u0003אחר חצות\u0004 ובהמשך נאמר שאם \u0003אין בנו ממונה עמו — יביאנו\u0004 הבן \u0003לשום\u0004 (לשם) \u0003שלמים\u0004, אולם \u0003הא קבעתיה\u0004 \u0005[הרי\u0006 כבר \u0005קבעה אותו]\u0006 שעת \u0003חצות\u0004 לצורך קרבן פסח ונמצא שהוא קרבן פסח שנראה ונדחה, וקרבן כזה צריך שירעה עד שיפול בו מום ויפלו דמיו לנדבה, אבל אין להקריבו שלמים!","\u0003אמר רבא: לעולם\u0004 יש לומר \u0003דמית\u0004 \u0005[שמת]\u0006 האב \u0003קודם חצות, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003יביאנו לשום פסח\u0004 — הכונה היא \u0003לשום פסח שני\u0004 שאז יהא לאחר זמן אנינות.","\u0003אביי אמר: לצדדין קתני\u0004 כלומר התוספתא מדברת בשני מקרים נבדלים וכך יש להבין: \u0003מת\u0004 האב \u0003אחר חצות\u0004 והיה \u0003בנו ממונה עמו — יביאנו לשום פסח\u0004 שחלה עליו בחצות חובת הקרבת פסח ודוחה אנינות לילה שמדברי סופרים. \u0003מת קודם חצות\u0004 ו\u0003אין בנו ממונה עמו — יביאנו לשום שלמים\u0004, שהרי לא נקבע בחצות להיות פסח. ובשני המקרים האחרים של מת לאחר חצות ולא היה בנו ממונה, או לפני חצות והיה בנו ממונה — אין התוספתא דנה.","\u0003רב שרביא אמר: לעולם\u0004 מדובר ש\u0003מת\u0004 האב \u0003לאחר חצות,\u0004 ובכל זאת יובא לשם שלמים ואינו נקרא דחוי \u0003וכגון שהיה אביו גוסס בחצות\u0004 שאין הקרבן נקבע בחצות לפסח ונדחה, כיון שידע מראש שרוב גוססים למיתה.","\u0003רב אשי אמר: לעולם\u0004 מדובר \u0003דמית\u0004 \u0005[שמת]\u0006 האב \u0003לאחר חצות\u0004 ותוספתא זו כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר אין בעלי חיים נדחין\u0004 ואין שעת חצות קובעת איפוא, כל עוד לא נשחט הקרבן.","\u0003רבינא אמר:\u0004 כאן מדובר \u0003כגון שהפרישו\u0004 את קרבן הפסח הזה \u0003אחר חצות ומתו בעלים אחר חצות, וקא סבר\u0004 \u0005[וסבר\u0006 תנא זה\u0005]\u0006 שעת \u0003חצות קבע\u0004 וכיון שבחצות עוד לא הופרש, לא יכול להדחות.","קרבן \u0003הפסח שנתערב בזבחים\u0004 (קרבנות) אחרים כגון אשם ועולה ולא ידוע לאיזה קרבן מיועדת כל בהמה \u0003כולן ירעו עד שיסתאבו\u0004 (יפול בהם מום) \u0003וימכרו ויביא בדמי היפה שבהן ממין זה ובדמי היפה שבהן ממין זה\u0004 שיקנה פסח בדמי היפה שבהם וכן שאר קרבנות \u0003ויפסיד המותר\u0004 (ההפרש) \u0003מביתו\u0004 שהרי לא כולם היו יפים כל כך ובכל זאת צריך להביא את כולם כאילו היה כל אחד מהם היפה שבכולם.","\u0003נתערב\u0004 הפסח \u0003בבכורות ר' שמעון אומר: אם\u0004 היו אלו שנתערבו קרבנותיהם \u0003חבורות כהנים — יאכלו\u0004 את כולם בליל הפסח שהרי להם מותר לאכול מבשר הבכור, ושחיטתו ושאר עבודותיו שוות לקרבן הפסח. ויאמר שמקריב את הפסח לשם פסח בכל מקום שהוא ואת הבכור לשם בכור בכל מקום שהוא."],["על דברי ר' שמעון המתיר לכהנים לאכול פסח שנתערב עם הבכורות מקשים: כיצד אפשר שיאכל הכל בתורת קרבן פסח, \u0003והא קא מייתי\u0004 \u0005[והרי הוא מביא]\u0006 \u0003קדשים לבית הפסול?\u0004 שהרי הבכור נאכל לשני ימים ולילה אחד והפסח נאכל רק באותו לילה, ונמצא שגורם לפסול את הבכורות טרם זמנם ולהביאם לידי שריפה.","ומשיבים: \u0003ר' שמעון לטעמיה\u0004 \u0005[לטעמו,ל\u0006שיטתו\u0005]\u0006 ש\u0003אמר\u0004 בכלל כי \u0003מביאין קדשים לבית הפסול\u0004 ואינו חושש. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אשם שנתערב בשלמים\u0004 מה יעשו בו? \u0003ר' שמעון אומר: ישחטו\u0004 את כולם \u0003בצפון\u0004 כאשם, שאף שהשלמים אינם טעונין שחיטה דווקא בצפון מותר לשחטם גם שם, \u0003ויאכלו כחומר שבהם\u0004 בתורת קדשי קדשים, כאילו היו שניהם אשם, ויאכלו ליום ולילה, בעזרה, ולא ייאכלו לשני ימים ולא יוציאום ויחלקום כקדשים קלים לקרובי הכהנים בכל העיר.","\u0003אמרו לו\u0004 חכמים: \u0003אין מביאין קדשים לבית הפסול\u0004 — שהרי שמא שלמים היו ועל ידי קיצור זמן אכילתם עשוי להביאם לידי פסול ולשריפה שלא כדין. ומשמע שר' שמעון אינו חושש לנימוק זה.","ושואלים: \u0003ורבנן, היכי עבדינן\u0004 \u0005[ו\u0006לשיטת \u0005חכמים, מה עושים]?\u0006 כשנתערב פסח בבכורות? שהרי הבכורות אינם ניתנים לפדייה, שקדושתם היא קדושה מרחם וחלה רק עליהם! ומשיבים: \u0003אמר רבא: נמתין לו עד שיוממו\u0004 (עד שיפול בהם מום) בכולם \u0003ויביא בהמה שמינה\u0004 מן החולין, \u0003ולימא\u0004 \u0005[ויאמר]:\u0006 \u0003כל היכא דאיתיה לפסח\u0004 \u0005[כל מקום שישנו הפסח]\u0006 \u0003תחול עליה דהאי\u0004 \u0005[על\u0006 בהמה שמינה \u0005זו]\u0006 קדושתו של הפסח ויקריב אותה בתורת שלמים \u0003ואכיל להו\u0004 \u0005[ויאכל אותם]\u0006 את המעורבים \u0003בתורת בכור בעל מום,\u0004 שנאכלים לכהנים כחולין, ויש בהם הגבלות מסויימות, שאין שוקלים ומוכרים אותם בבזיון, וכדומה.","\u0003חבורה שאבד פסחה ואמרו לאחד\u0004 מהם: \u0003צא ובקש\u0004 (חפש) את הפסח וכשתמצאנו ת\u0003שחוט\u0004 אותו \u0003עלינו\u0004 (עבורנו). \u0003והלך ומצא\u0004 את בהמת הקרבן \u0003ושחט\u0004 עבור כולם, ובינתים \u0003הם לקחו\u0004 בהמה אחרת \u0003ושחטו\u0004 אותה לשם פסח. מעתה, \u0003אם\u0004 הפסח \u0003שלו נשחט ראשון הוא אוכל משלו\u0004 שהרי הוא מנוי על קרבן זה \u0003והם אוכלין עמו משלו\u0004 שהרי המנה עליו את כל החבורה ושל כולם הוא, והשני ישרף, שהרי אין לו בעלים. \u0003ואם שלהן נשחט ראשון — הם אוכלין משלהן\u0004 שהרי בעצם שחיטת השני משכו ידיהם מן הראשון. \u0003והוא אוכל משלו\u0004 שהרי הוא לא נמנה על פסח שלהם.","\u0003ואם אינו ידוע איזה מהן נשחט ראשון, או ששחטו שניהם כאחד — הוא אוכל משלו, והם אינם אוכלין עמו\u0004 שמא שלהם נשחט קודם \u0003ושלהן יצא לבית השריפה\u0004 שהרי אינם יכולים לאכול ממנו שמא נשחט שני, והם מנויים על הראשון. אבל \u0003פטורין מלעשות פסח שני\u0004 שכן בזמן שחיטה היו בני החבורה מוכנים וראויים ורק אונס הוא שאירע להם, שלא יוכלו לקיים את המצוה בפועל והאכילה עצמה אינה מעכבת.","מקרה שונה במקצת בענין אבידת קרבן פסח הוא, כאשר אבד קרבן הפסח לבני החבורה ושלחו אחד מהם לבקשו ו\u0003אמר להן\u0004 השליח לבני חבורתו טרם צאתו: \u0003אם אחרתי — צאו ושחטו עלי\u0004 פסח \u0003הלך\u0004 הוא עצמו \u0003ומצא\u0004 את הפסח שאבד \u0003ושחט והן לקחו\u0004 בינתים \u0003ושחטו\u0004 פסח אחר. \u0003אם שלהן נשחט ראשון — הן אוכלין משלהן והוא אוכל עמהן\u0004 שהרי אמר להם לשחוט עבורו והמנוהו על פסחם. \u0003ואם שלו נשחט ראשון — הוא אוכל משלו והן אוכלין משלהם\u0004 שהרי בכך ששחטו אחר משכו ידיהם מן הראשון.","\u0003ואם אינו ידוע איזה מהן נשחט ראשון או ששחטו שניהם כאחד — הן אוכלין משלהן\u0004 שהרי מכל מקום משכו ידיהם מן הראשון בכך ששחטו אחר שהוא ודאי שלהם היה, \u0003והוא אינו אוכל עמהן\u0004 שהרי גמר בליבו להמנות על הפסח האחר ולא ברור אם שלו קדם. ולכן \u0003שלו יצא לבית השריפה, ופטור מלעשות פסח שני.\u0004","\u0003אמר להן\u0004 שאם יאחר שישחטו עליו פסח \u0003ואמרו לו\u0004 שאם ימצא שישחט עבורם — \u0003אוכלין כולן מן הראשון\u0004 שנשחט. \u0003ואם אין ידוע איזה מהן נשחט ראשון — שניהן יוצאין לבית השריפה\u0004 ופטורים מפסח שני.","ואם \u0003לא אמר להן ולא אמרו לו,\u0004 שלא יפו זה את כוחו של זה לשחוט עבורם — \u0003אין אחראין זה לזה,\u0004 ובני החבורה אוכלים משלהם, והוא אוכל משלו, שהרי הוא נמנה על שלו ושוב איננו קשור בקרבן אחר, והם בשחיטת האחר משכו ידיהם מן הפסח שאבד.","\u0003שתי חבורות שנתערבו פסחיהן\u0004 ואינם יודעים איזה מהם שייך לכל חבורה, כך יעשו: \u0003אלו מושכין להן אחד\u0004 מן הפסחים \u0003ואלו מושכין להן אחד. אחד מאלו\u0004 מבני חבורה אחת \u0003בא לו אצל אלו\u0004 בני החבורה האחרת, \u0003ואחד מאלו\u0004 מבני החבורה האחרת \u0003בא לו אצל אלו\u0004 בני החבורה הראשונה, \u0003וכך הם אומרים\u0004 בני כל חבורה לאותו אחד שבא מן החבורה האחרת: \u0003אם שלנו הוא הפסח הזה\u0004 שעתה בידינו \u0003— ידיך משוכות\u0004 מהפסח שהיה \u0003שלך ונמנית\u0004 על הפסח \u0003שלנו\u0004 ואתה רשאי לאכול בו. \u0003ואם שלך הוא הפסח הזה\u0004 שהוא היה שייך באמת לבני חבורה האחרת ולך בכללם, הרי \u0003ידינו משוכות משלנו ונמנינו על שלך\u0004 ואתה יכול לזכותו לנו. וכן יעשו בני החבורה האחרת.","\u0003וכן\u0004 אם היו \u0003חמש חבורות של חמשה חמשה\u0004 אנשים או \u0003של עשרה עשרה\u0004 אנשים — \u0003מושכין להן אחד מכל חבורה וחבורה וכן הם אומרים\u0004 כדרך שאומרים בשתי חבורות, שמזכים לו חלק בקרבנם אם אין הפסח שלו, או זוכים ונמנים על קרבנו אם שלו הוא, כך אומרים לכל אחד מבני החבורות האחרות.","\u0003שנים שנתערבו פסחיהן\u0004 וכל אחד היה מנוי לבדו על הפסח, מה יעשו? \u0003זה מושך לו אחד\u0004 מן הפסחים, \u0003וזה מושך לו אחד, זה ממנה עמו\u0004 על פסחו \u0003אחד מן השוק וזה ממנה עמו אחד מן השוק,\u0004","ואחר כך \u0003זה בא אצל זה וזה בא אצל זה, וכך הם אומרים: אם שלי הוא פסח זה — ידיך משוכות משלך ונמנית על שלי, ואם שלך הוא פסח זה — ידי משוכות משלי ונמניתי על שלך,\u0004 כמעשה בשתי חבורות. והצורך להימנות על כל קרבן עוד אחד מן השוק הוא כדי שבשעה שכל אחד מהם נמשך מפסחו ונמנה על של חברו, לא ישאר פסחו ללא בעלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמר להן\u0004 שאם יקדימו הם ישחטו את הפסח עבורו, \u0003ואמרו לו\u0004 שאם הוא יקדים, ישחט הוא עבורם — \u0003אוכל\u0004 גם הוא וגם הם \u0003מן\u0004 הפסח \u0003הראשון\u0004 שנשחט, והשני נשרף. \u0003לא אמר להן ולא אמרו לו — אינן אחראין זה לזה,\u0004 וכל אחד אוכל משלו."],["\u0003מכאן אמרו חכמים: יפה שתיקה לחכמים, קל וחומר לטפשים.\u0004 שהרי במקרה שלא אמרו דבר לא הם ולא הוא — הכל יהיה מתוקן ויהיה ניתן לאכול משתי הקרבנות כל אחד משל עצמו, אבל כשאמרו גם הם וגם הוא \u0003—\u0004 רק הראשון נאכל ואילו השני יוצא לשריפה. וכן \u0003נאמר:\u0004 \"גם \u0003אויל מחריש חכם יחשב\u0004 אוטם שפתיו נבון\" (משלי יז, כח).","במשנה דובר על \u0003שנים שנתערבו פסחיהם\u0004 מה יעשו. ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר: \u0003\"ואם ימעט הבית מהיות משה\"\u0004 (שמות יב, ד), \u0003מלמד\u0004 הכתוב \u0003שמתמעטין והולכין\u0004 בני החבורה ומושכים ידיהם מן הקרבן \u0003ובלבד שיהא אחד מבני חבורה\u0004 הראשונה \u0003קיים,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר:\u0004 לא כן, \u0003ובלבד שלא יניחו את הפסח כמות שהוא,\u0004 שלא יהא הפסח זמן כלשהו בלא כל בעלים. ולכאורה במשנתנו כיון שבני שתי החבורות הראשונים מוותרים כל אחד על פסחו והוא מצוי בידו של אדם שנוסף מן השוק ואינו מן המנויים הראשונים, הרי זה שלא כשיטת ר' יהודה! \u0003אמר ר' יוחנן: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' יהודה\u0004, כי \u0003כיון\u0004 ש\u0003אמר ר' יהודה\u0004 במקום אחר \u0003אין שוחטין את הפסח על היחיד\u0004 וחייבים להיות לפחות שני מנויים, הרי פסח זה שהיה בבעלותו של יחיד \u0003מעיקרא לאמנויי אחרינא בהדיה קאי\u0004 \u0005[מתחילה\u0006 פסח זה \u0005שימנה\u0006 עוד אחר \u0005עמו עומד]\u0006 ואותו שנצטרף לאחר מכן \u0003כאחד מבני חבורה דמי\u0004 \u0005[נחשב],\u0006 שהרי מתחילה היה על דעת כן. \u0003אמר רב אשי: מתניתין נמי דייקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטת ר' יהודה, \u0003דקתני\u0004 \u0005[ששנינו\u0006 בה\u0005]:\u0006 \u0003וכן חמש חבורות של חמשה חמשה\u0004. ונדייק \u0003של חמשה — אין\u0004 \u0005[כן]\u0006 שאז אפשר להשתמש בתקנה זו שילכו ארבעה מהם לחבורות האחרות. \u0003אבל\u0004 ארבע חבורות \u0003של חמשה\u0004 מנויים ואחת של \u0003ארבעה\u0004 מנויים \u0003— לא\u0004 נאמרו במשנה, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003לא פייש חד\u0004 \u0005[נשאר אחד]\u0006 \u0003מבני חבורה\u0004 ראשונה \u0003גביה\u0004 \u0005[לידו],\u0006 שהרי אם ילך מחבורה זו מנוי אחד לכל אחת מהארבע חבורות האחרות, הרי שלא ישארו בחבורה זו אף אחד ממנוייה הראשונים ואין לעשות שיהא קרבן הפסח בלא אחד מבני חבורה הראשונה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמשנתנו כשיטת ר' יהודה היא.","","",""],["\u0003ערב פסחים סמוך ל\u0004זמן \u0003מנחה — לא יאכל אדם עד שתחשך,\u0004 כדי שיוכל לאכול בלילה את המצה לתיאבון. \u0003אפילו עני שבישראל לא יאכל\u0004 סעודת ליל פסח \u0003עד שיסב\u0004 מוטה על צידו כדרך שמסובין העשירים ובני החורין, \u0003ולא יפחתו לו\u0004 גבאי צדקה לצורך סעודה זו \u0003מארבע כוסות של יין ואפילו\u0004 הוא עני שבעניים המקבל \u0003מן התמחוי\u0004 (כלי שהיו אוספים בו מזונות לעניים), צריך לתת לו ארבע כוסות יין בלילה זה.","על ההלכה שאין לאכול בערב הפסח סמוך למנחה תוהים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 נאמר הדבר ב\u0003ערבי פסחים? אפילו בערבי שבתות\u0004 ושאר ערבי \u0003ימים טובים נמי\u0004 \u0005[גם כן]\u0006 אסור מזמן המנחה והלאה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יאכל אדם בערבי שבתות וימים טובים מן המנחה ולמעלה\u0004 (והלאה) \u0003כדי שיכנס לשבת כשהוא\u0004 מלא \u0003תאוה\u0004 לאכול, כדי שתהא סעודת השבת ערבה לו, אלו \u0003דברי ר' יהודה. ר' יוסי אומר: אוכל והולך עד שתחשך\u0004 ואינו מקפיד.","\u0003אמר רב הונא: לא צריכא\u0004 \u0005[נצרכה]\u0006 משנתנו לחדש \u0003אלא\u0004 לשיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: אוכל והולך עד שתחשך\u0004 ולשיטתו יש להדגיש \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שאוכל והולך עד שתחשך, אמורים \u0003בערבי שבתות וימים טובים, אבל בערב הפסח, משום חיובא דמצה\u0004 \u0005[חובת\u0006 אכילת \u0005המצה]\u0006 \u0003מודה\u0004 ר' יוסי שראוי לאכלה ברצון ולתיאבון ולכן אין לאכול כבר מן המנחה ולמעלה.","\u0003רב פפא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' יהודה\u0004 ובכל זאת יש הבדל, \u0003התם\u0004 \u0005[שם]\u0006 \u0003בערבי שבתות וימים טובים מן המנחה ולמעלה הוא דאסיר\u0004 \u0005[שאסור],\u0006 אבל \u0003סמוך למנחה שרי\u0004 \u0005[מותר].\u0006 \u0003אבל בערב הפסח, אפילו סמוך למנחה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004 ודין זה הוא שחידשה משנתנו להבדיל מערב שבתות וימים טובים.","ושואלים: והאם \u0003בערב שבת סמוך למנחה שרי\u0004 \u0005[מותר]\u0006 לאכול? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יאכל אדם בערב שבת וימים טובים מתשע שעות ולמעלה, כדי שיכנס לשבת כשהוא\u0004 מלא \u0003תאוה\u0004 לאכול, אלו \u0003דברי ר' יהודה\u0004, \u0003ר' יוסי אומר: אוכל והולך עד שתחשך.\u0004 אם כן ר' יהודה אומר שגם בערב שבת אסור לאכול עוד לפני זמן מנחה קטנה (שהוא בתשע ומחצה)!","\u0003אמר מר זוטרא: מאן לימא לן דמתרצתא\u0004 \u0005[מי יאמר לנו ש\u0006ברייתא זו \u0005מיושבת\u0006 ונכונה] \u0003היא\u0004 בגרסתה?"],["\u0003דילמא משבשתא\u0004 \u0005[שמא משובשת]\u0006 \u0003היא\u0004 ברייתא זו ואין להקשות ממנה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מרימר, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יימר: אנא איקלעי לפירקיה\u0004 \u0005[אני הזדמנתי לדרשת\u0006 הרגל\u0005]\u0006 של \u0003רב פנחס בריה\u0004 \u0005[ בנו]\u0006 של \u0003רב אמי, וקם תנא ותני קמיה\u0004 \u0005[ועמד חוזר המשניות ושנה\u0006 ברייתא זו \u0005לפניו]\u0006 \u0003וקיבלה מיניה\u0004 \u0005[ממנו],\u0006 והרי זו הוכחה שהיא מוסכמת ומתוקנת. ומעירים: \u0003אי הכי קשיא\u0004 \u0005[אם כך קשה]\u0006 מה שהקשינו על רב פפא! \u0003אלא\u0004 עלינו לחזור מתירוץ זה ולומר כי \u0003מחוורתא\u0004 \u0005[ברור ]\u0006 הדבר \u0003כ\u0004שיטת \u0003רב הונא\u0004 שמשנתנו היא כשיטת ר' יוסי ואף שבערבי שבתות וימים טובים אוכל והולך עד שתחשך, מכל מקום בערב פסח אסור באכילה משעת המנחה ולמעלה.","ושואלים: \u0003ולרב הונא מי ניחא\u0004 \u0005[האם\u0006 באמת \u0005נוח],\u0006 והאם לדבריו מתיישבות השיטות? והלא \u0003אמר ר' ירמיה אמר ר' יוחנן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' אבהו אמר ר' יוסי בר ר' חנינא: הלכה כר' יהודה בערב הפסח, והלכה כר' יוסי בערב שבת.\u0004","ונדייק: כיון שהוצרך לומר כי \u0003הלכה כר' יהודה בערב הפסח, מכלל\u0004 הדברים אתה לומד \u0003דפליג\u0004 \u0005[שחלק]\u0006 \u0003ר' יוסי בתרוייהו\u0004 \u0005[בשניהם]\u0006 גם בערב הפסח וגם בשבתות וימים טובים, ואם כן אי אפשר לייחס לו את משנתנו!","ודוחים: \u0003לא,\u0004 כך יש להבין: \u0003הלכה\u0004 הכוונה היא, \u0003מכלל\u0004 הדברים נלמד \u0003דפליגי\u0004 \u0005[שנחלקו]\u0006 בענין \u0003הפסקה.\u0004 שאף ר' יוסי מודה שאין ראוי להתחיל לאכול בערב הפסח משעת המנחה ולמעלה, אבל לדעתו אם כבר התחיל לאכול והגיע חג הפסח — אינו צריך להפסיק.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שאף בהפסקה נחלקו: אנשים שהיו מסובים ואוכלים בערב שבת \u0003מפסיקין לשבתות\u0004 ואין אוכלים עוד מכניסת השבת אלא מסיטים את השולחן מלפניהם (שהיו להם שולחנות קטנים לכל אחד לחוד) ומתפללים ערבית ומקדשים על היין ואחר כך אוכלים, אלו \u0003דברי ר' יהודה. ר' יוסי אומר: אין מפסיקין.\u0004","ומספרים: \u0003ומעשה ברבן שמעון בן גמליאל ור' יהודה ור' יוסי שהיו מסובין\u0004 יחדיו \u0003בעכו\u0004 ביום השישי ואכלו \u0003וקדש עליהם היום\u0004 (השבת), \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן שמעון בן גמליאל לר' יוסי: ברבי\u0004 (תואר לאדם גדול ומיוחס), האם \u0003רצונך\u0004 ש\u0003נפסיק וניחוש\u0004 (נחשוש) \u0003לדברי יהודה חבירנו\u0004 הסבור שיש להפסיק?","\u0003אמר לו: בכל יום ויום אתה מחבב דבריי לפני ר' יהודה\u0004 ופוסק הלכה כמותי, \u0003ועכשיו אתה מחבב דברי ר' יהודה בפני?\u0004 והשתמש במליצה בלשון הכתוב: \u0003\"הגם לכבוש את המלכה עמי בבית\"\u0004 (אסתר ז, ח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן שמעון: \u0003אם כן\u0004 שאתה סבור שהדבר יתפרש כפסיקת הלכה \u0003לא נפסיק,\u0004 שיש לחשוש \u0003שמא יראו התלמידים\u0004 שהפסקנו \u0003ויקבעו הלכה לדורות\u0004 כר' יהודה שלא כרצוננו. \u0003אמרו\u0004 חכמים לאחר מכן: אכן, \u0003לא זזו משם עד שקבעו הלכה כר' יוסי\u0004 שאין צורך להפסיק.","\u0003אמר רב יהודה אמר שמואל:\u0004 לענין הפסקה זו \u0003אין הלכה לא כר' יהודה\u0004 שאמר שמפסיקים לגמרי ומזיזים את השלחן ממקומו \u0003ולא כר' יוסי\u0004 שאמר שאין מפסיקים כלל, \u0003אלא פורס מפה\u0004 על השולחן \u0003ומקדש\u0004 את השבת, וממשיך סעודתו. ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב תחליפא בר אבדימי אמר שמואל: כשם שמפסיקין ל\u0004צורך \u0003קידוש\u0004"],["\u0003כך מפסיקין להבדלה\u0004 שאם היו מסובים לסעודתם בשבת עד הלילה — מפסיקים אכילתם ומבדילים\u0003.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מפסיקין? לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003לעקירת שולחן\u0004 שיש להוציא אותו ממקומו? כשיטת ר' יהודה. ועונים: \u0003לא,\u0004 הכוונה היא לפריסת \u0003מפה,\u0004 שאף להבדלה אין צורך בדבר אחר.","מסופר: \u0003רבה בר רב הונא איקלע לבי ריש גלותא\u0004 \u0005[הזדמן לבית ראש הגולה]\u0006 והיו מסובים לאכול, ו\u0003אייתו תכא קמיה\u0004 \u0005[הביאו שולחן לפניו]\u0006 שיאכל אף הוא, וכיון שנתקדשה שבת \u0003פרס מפה וקידש. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ושוין שאין מביאין את השולחן אלא אם כן קידש\u0004 תחילה, \u0003ואם הביא\u0004 את השולחן קודם קידוש \u0003פורס מפה\u0004 עליו \u0003ומקדש.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 בנושא זה: \u0003שוין\u0004 ר' יהודה ור' יוסי החולקים בענין היתר אכילה בערב שבת מן המנחה ולמעלה וכן לענין הפסקה \u0003שאין מתחילין\u0004 בסעודה, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003שוין שמתחילין.\u0004 ומעתה נברר: \u0003בשלמא הא דתניא\u0004 \u0005[נניח אותה\u0006 ברייתא \u0005ששנויה]\u0006 \u0003שוין שאין מתחילין — משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 מתקיימת \u0003בערב הפסח,\u0004 שגם ר' יוסי מסכים שלכתחילה אין מתחילים בסעודה,","\u0003אלא\u0004 ברייתא \u0003הא דתניא\u0004 \u0005[זו ששנויה]\u0006 \u0003שוין שמתחילין — אימת\u0004 \u0005[אימתי]\u0006 מדובר? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שמדובר \u0003בערב שבת — הא מיפלג פליגי\u0004 \u0005[הרי חלוקים הם]\u0006 בדין זה, האם מותרת בו האכילה מן המנחה ולמעלה! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 שלא נחלקו — היה זה \u0003קודם תשעה\u0004 (תשע שעות), כלומר קודם לשעה תשיעית ביום, ולדעת כולם עדיין מותר להתחיל לאכול. \u0003כאן\u0004 שנחלקו אם מתחילין — הרי זה \u0003לאחר תשעה\u0004.","ועוד בעניני קידוש היום. \u0003אותם בני אדם שקידשו בבית הכנסת\u0004 לפי המנהג שלאחר התפילה היו מקדשים בבית הכנסת על היין, \u0003אמר רב: ידי\u0004 חובת שתיית \u0003יין\u0004 בקידוש \u0003לא יצאו,\u0004 ואם יש יין בביתם — חייבים לברך שנית על היין, שלא יצאו ידי חובה בברכה ששמעו בבית הכנסת שכן לא נשארו שם לסעודה. ואולם \u0003ידי\u0004 חובת \u0003קידוש — יצאו\u0004 שהרי שמעוהו כבר. \u0003ושמואל אמר:\u0004"],["\u0003אף ידי קידוש לא יצאו,\u0004 וחייבים לקדש שנית בביתם. ושואלים: \u0003אלא לרב, למה ליה לקדושי\u0004 \u0005[לו לקדש]\u0006 שנית \u0003בביתיה\u0004 \u0005[בביתו]?\u0006 הלא יצא כבר ידי חובה! ומשיבים: אכן, יצא, ומקדש \u0003כדי להוציא בניו ובני ביתו\u0004 שלא היו בבית הכנסת.","ושואלים: \u0003ו\u0004לשיטת \u0003שמואל למה לי לקדושי בבי כנישתא\u0004 \u0005[לקדש בבית הכנסת]\u0006 אם אינו יוצא בכך כלל? ומשיבים: שנעשה הדבר \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את ה\u0003אורחים ידי חובתן,\u0004 שאותם אורחים \u0003אכלו ושתו וגנו בבי כנישתא\u0004 \u0005[אוכלים ושותים וישנים בבית הכנסת],\u0006 וכיון שבית הכנסת הוא מקום דירתם צריכים הם לשמוע קידוש שם.","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר שמואל: אין קידוש אלא במקום סעודה,\u0004 ואם אינו אוכל במקום הקידוש — אינו יוצא ידי חובת קידוש. \u0003סבור מינה\u0004 \u0005[היו סבורים\u0006 הלומדים \u0005מ\u0006אמרתו \u0005זו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים רק כשיוצא \u0003מבית לבית\u0004 שאינו יוצא ידי חובת קידוש אם אוכל את סעודתו בבית אחר. \u0003אבל\u0004 הלך \u0003ממקום\u0004 שקידש בו \u0003למקום\u0004 אחר \u0003בחד ביתא\u0004 \u0005[בבית אחד,\u0006 באותו בית\u0005]\u0006 כדי לסעוד בו — \u0003לא,\u0004 אלא יצא ידי חובת קידוש.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ענן בר תחליפא\u0004 ללומדים: \u0003זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים רבות הייתי עומד לפני]\u0006 \u0003שמואל, ונחית מאיגרא לארעא והדר\u0004 \u0005[והיה יורד מן הגג\u0006 מקומה שניה \u0005לקרקע וחוזר]\u0006 ו\u0003מקדש.\u0004 משמע שאף באותו בית אין יוצאים חובת קידוש ממקום למקום.","ולעצם הדין מעירים: \u0003ואף רב הונא סבר\u0004 ש\u0003אין קידוש אלא במקום סעודה.\u0004 וראיה לדבר ש\u0003רב הונא קדיש, ואיתעקרא ליה שרגא\u0004 \u0005[קידש, ונעקר,\u0006 כבה, \u0005לו הנר]\u0006 ולא יכול היה לאכול בחושך, \u0003ועיילי ליה למניה לבי גנניה דרבה בריה דהוה שרגא\u0004 \u0005[והכניסו את חפציו לבית חופתו של רבה בנו שהיה\u0006 בו \u0005נר]\u0006 \u0003וקדיש וטעים מידי\u0004 \u0005[וקידש\u0006 שנית \u0005וטעם משהו],\u0006 \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 רב הונא: \u0003אין קידוש אלא במקום סעודה.\u0004","ומעירים: \u0003ואף רבה סבר אין קידוש אלא במקום סעודה.\u0004 ש\u0003אמר אביי: כי הוינא בי מר\u0004 \u0005[כאשר הייתי בבית אדוני,\u0006 רבה\u0005],\u0006 \u0003כי הוה\u0004 \u0005[כאשר היה]\u0006 \u0003מקדש אמר לן\u0004 \u0005[לנו]:\u0006 \u0003טעימו מידי, דילמא אדאזליתו לאושפיזא מתעקרא לכו שרגא\u0004 \u0005[טעמו\u0006 פה \u0005דבר מה, שמא עד שאתם הולכים למלונכם יעקר\u0006 יכבה, \u0005הנר]\u0006 \u0003ולא מקדש לכו\u0004 \u0005[תוכלו לעשות קידוש]\u0006 \u0003בבית אכילה, ובקידושא דהכא\u0004 \u0005[ובקידוש של כאן]\u0006 אתם \u0003לא נפקיתו\u0004 \u0005[יוצאים],\u0006 ש\u0003אין קידוש אלא במקום סעודה.\u0004","על הלכה אחרונה זו תוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: כל מילי דמר הוה עביד\u0004 \u0005[דבריו,\u0006 מנהגיו, \u0005של אדוני\u0006 רבה, \u0005היה עושה]\u0006 \u0003כרב, לבר מהני תלת דעביד\u0004 \u0005[חוץ משלשה אלה שהיה עושה]\u0006 \u0003כשמואל,\u0004 והם: \u0003מתירין\u0004 ציצית \u0003מבגד לבגד\u0004 כשמואל, ואין חוששים כרב שיש בכך משום בזיון וביטול למצוה. \u0003ומדליקין\u0004 נרות חנוכה \u0003מנר לנר,\u0004 ואין חוששים כרב שיש בכך חשש של שימוש חול בנר של מצוה. \u0003והלכה כר' שמעון\u0004 בענין \u0003גרירה\u0004 בשבת.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: גורר אדם מטה כסא וספסל בשבת\u0004 אם קשה לו להרימם \u0003ובלבד שלא יתכוין לעשות\u0004 מלכתחילה \u0003חריץ\u0004 בקרקע. ואם נעשה מאליו — אין לחשוש, שדבר שאין מתכוון מותר. ואם כן, מדוע לא נהג רבה אף בענין זה כשיטת רב?","ומשיבים: \u0003כחומרי\u0004 \u0005[כחומרותיו]\u0006 של \u0003רב הוה עביד\u0004 \u0005[היה עושה]\u0006\u0003, כקולי\u0004 \u0005[כקולותיו]\u0006 של רב \u0003לא הוה עביד\u0004 \u0005[היה עושה],\u0006 ורק בשלשה דברים אלה היה פוסק לקולא שלא כשיטת רב, אבל בענין קידוש שרב מיקל בו — לא נהג כמותו.","\u0003ור' יוחנן אמר:\u0004 לא רק שיוצא ידי קידוש בקידוש של בית הכנסת, אלא \u0003אף ידי יין נמי\u0004 \u0005[גם כן]\u0006 \u0003יצאו,\u0004 שאין צריכים לחזור ולברך על היין הבא בתוך סעודתם בביתם, שמתוך שדעתם לילך לסעוד בביתם, ודאי לא הסיחו דעתם בינתיים. ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' יוחנן\u0004 בענין זה \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר ר' חנין בר אביי אמר ר' פדת אמר ר' יוחנן: אחד שינוי\u0004 סוג ה\u0003יין\u0004 כשהיה שותה יין והביאו לו יין ממין חדש,"],["\u0003ואחד שינוי מקום\u0004 שעברו האוכלים ממקום למקום — \u0003אין צריך לברך\u0004 פעם שניה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא שבה נאמר: \u0003שינוי מקום — צריך לברך, שינוי יין — אין צריך לברך,\u0004 והיא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 והושבו דבריו.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אידי בר אבין קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב חסדא וקאמר\u0004 \u0005[ואמר]\u0006 הלכה \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב הונא: הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת\u0004 כי בשעת \u0003שינוי מקום\u0004 ממקום הקידוש למקום הסעודה \u0003צריך לברך, לא שנו אלא\u0004 כשמשנה מקומו \u0003מבית לבית, אבל\u0004 אם משנה מקומו \u0003ממקום למקום\u0004 באותו בית — \u0003לא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אידי בר אבין: הכי תנינא ליה במתניתא דבי רב הינק\u0004 \u0005[כך שנינו זאת במשנתו של בית\u0006 מדרשו \u0005של רב הינק],\u0006 \u0003ואמרי ליה במתניתא דבי בר הינק כוותיך\u0004 \u0005[ויש אומרים\u0006 שאמר לו: \u0005בברייתא של בית\u0006 מדרשו של \u0005בן הינק\u0006 שנויה \u0005כשיטתך].\u0006 ושואלים: אם כן שיש ברייתא כזו, וכי \u0003רב הונא מתניתא קא משמע לן\u0004 \u0005[ברייתא רצה להשמיענו]\u0006 ומדוע אמרה בשמו? ומתרצים: \u0003רב הונא מתניתא\u0004 \u0005[\u0006אותה \u0005ברייתא]\u0006 \u0003לא שמיע ליה\u0004 \u0005[שמע,\u0006 ידע, \u0005אותה]\u0006 ומעצמו חידש הלכה זו.","\u0003ותו\u0004 \u0005[ועוד]\u0006 מסופר באותו ענין: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חסדא וקאמר משמיה דנפשיה\u0004 \u0005[ואמר משם עצמו]\u0006 ולא בשם רבותיו: \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת\u0004 כי בשעת \u0003שינוי מקום\u0004 ממקום הקידוש למקום הסעודה \u0003צריך לברך, לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 אם היתה סעודתו \u0003בדברים שאין טעונין ברכה\u0004 חשובה, \u0003לאחריהן\u0004 כגון מים או פירות שאינם חשובים שצריך האוכל לאומרה דווקא \u0003במקומן,\u0004 כלומר, במקום שאכלם, ולכן עמידתו ללכת למקום אחר הוכיחה שסיים סעודתו ולכן אם הוסיף לאכול מהם במקום אחר הרי זו סעודה בפני עצמה וצריך לחזור ולברך,","\u0003אבל\u0004 אם אכל \u0003דברים הטעונין ברכה\u0004 חשובה \u0003לאחריהן\u0004 כגון שבעת המינים, ולכן צריכה שתיאמר דווקא \u0003במקומן,\u0004 הרי עמידתו ממקומו לא הוכיחה דבר על סיום הסעודה, ולכן אם הלך למקום אחר והוסיף לאכול שם מאותם פירות — \u0003אין צריך לברך\u0004 ברכה שניה נוספת לפני האכילה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לקיבעא קמא הדר\u0004 \u0005[לקביעות הראשונה חוזר]\u0006 ובודאי דעתו כשאוכל במקום אחר שהוא ממשיך את סעודתו הראשונה. \u0003ורב ששת אמר: אחד זה ואחד זה\u0004 אם עמד ממקומו והלך למקום אחר והוסיף שם ואכל מאותם דברים \u0003— צריך\u0004 לחזור ו\u0003לברך.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב חסדא מברייתא: \u0003בני חבורה שהיו מסובין לשתות, ועקרו רגליהן לצאת לקראת חתן או לקראת כלה, כשהן יוצאין — אין טעונין ברכה למפרע\u0004 (ברכה אחרונה) על המזון שאכלו, \u0003כשהן חוזרין — אין טעונין ברכה לכתחלה\u0004 (ברכה ראשונה) על המזון שיאכלו.","\u0003במה דברים אמורים — שהניחו שם\u0004 באותו מקום \u0003זקן או חולה\u0004 שאינו יכול ללכת, שאפשר לומר שיש עוד קבע לסעודה זו, \u0003אבל\u0004 אם \u0003לא הניחו שם לא זקן ולא חולה,\u0004 הרי \u0003כשהן יוצאין\u0004 ממקומם — \u0003טעונין ברכה למפרע\u0004 ו\u0003כשהן חוזרין — טעונין ברכה לכתחלה.\u0004","ונדייק: \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 \u0003עקרו רגליהן,\u0004 הרי מלשון זו משמע ש\u0003בדברים הטעונין ברכה לאחריהן במקומן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שלשון עקירה משמעה שסעודה זו היתה כדרכה צריכה עוד להמשך והיתה צריכה ברכה אחרונה אבל הם נעקרו מסיבה כלשהי טרם זמנם והולכים, \u0003וטעמא\u0004 \u0005[והטעם,\u0006 דוקא\u0005]\u0006 ש\u0003הניחו שם זקן או חולה הוא\u0004 ש\u0003כשהן יוצאין אין טעונין ברכה למפרע וכשהן חוזרין אין טעונין ברכה לכתחלה,\u0004","\u0003אבל\u0004 אם \u0003לא הניחו שם זקן או חולה\u0004 אף אחד, הרי \u0003כשהן יוצאין טעונין ברכה למפרע \u0004 — מברכים ברכה אחרונה על מה שאכלו \u0003וכשהן חוזרין טעונין ברכה\u0004 \u0005[מברכים]\u0006 \u0003לכתחלה,\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטת \u0003רב חסדא\u0004 הסובר שאפילו לא חזרו למקומם אלא המשיכו סעודתם במקום אחר, אינם צריכים לחזור ולברך בתחילה!","\u0003אמר רב נחמן בר יצחק:\u0004"],["\u0003מאן תנא\u0004 \u0005[מי הוא\u0006 החכם \u0005השונה]\u0006 בדבריו ענין \u0003עקירות\u0004 שאפילו דבר הטעון ברכה חשובה לאחריו, אם עקר האוכל ממקומו צריך לחזור ולברך,","\u0003ר' יהודה\u0004 הוא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חברים שהיו מסובין, ועקרו רגליהם לילך לבית הכנסת או לבית המדרש, כשהן יוצאין — אין טעונין ברכה למפרע\u0004 (אחרונה) על מה שאכלו \u0003וכשהן חוזרין — אין טעונין ברכה לכתחלה\u0004 (ראשונה). \u0003אמר ר' יהודה במה דברים אמורים — בזמן שהניחו שם מקצת חברים, אבל לא הניחו שם מקצת חברים, כשהן יוצאין — טעונין ברכה למפרע, וכשהן חוזרין — טעונין ברכה לכתחלה\u0004 ואם כן ברייתא זו שהקשינו ממנה על דברי רב חסדא דעת יחיד היא, ורב חסדא סבור כחכמים.","מברייתא זו מוסיפים ומדקדקים \u0003אלא טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 הוא אם אכל \u0003בדברים הטעונין ברכה\u0004 חשובה \u0003לאחריהן\u0004 שצריכה להיאמר דווקא \u0003במקומן,\u0004 אז הדין ש\u0003כשהן יוצאין — אין טעונין ברכה למפרע, וכשהן חוזרין — אין טעונין ברכה לכתחלה. אבל\u0004 אם אכל \u0003דברים שאין טעונין ברכה\u0004 חשובה \u0003לאחריהן\u0004 שצריכה להיאמר דווקא \u0003במקומן,\u0004 צריך לומר ש\u0003אפילו לרבנן\u0004 שאינם מצריכים ברכה נוספת בשעת שינוי מקום, הרי \u0003כשהן יוצאין\u0004 ממקומם \u0003— הריהם טעונין ברכה למפרע\u0004 (אחרונה) \u0003וכשהן חוזרין — הריהם טעונין ברכה לכתחלה\u0004 (ראשונה),","ואם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא זו קושיה חמורה]\u0006 לדברי \u0003ר' יוחנן\u0004 שאמר שעל שינוי מקום אין צורך לברך כלל! ותוהים: \u0003ולאו מי אותביניה חדא זימנא\u0004 \u0005[ו\u0006כי \u0005לא\u0006 דחינו, \u0005השבנו,\u0006 דבריו \u0005פעם אחת],\u0006 וכיון שכך שוב אין טעם עוד להקשות עליהם! ואומרים: אמנם כן הוא, ואולם \u0003נימא מהא נמי תיהוי תיובתא\u0004 \u0005[מכאן גם כן תהיה זו קושיה חמורה\u0006 עליו\u0005]!\u0006","ודוחים: אין ראיה גמורה, כי \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' יוחנן: הוא הדין\u0004 ש\u0003אפילו דברים שאין טעונין ברכה לאחריהם במקומן נמי\u0004 \u0005[גם כן]\u0006 \u0003אין צריך לברך\u0004 עליהם ברכה חדשה, \u0003והא דקתני\u0004 \u0005[וזו ששנינו]\u0006 בלשון \u0003\"עקרו רגליהן\"\u0004 שממנה כבר למדנו שמדובר בדברים הטעונים ברכה אחרונה, דבר זה בא \u0003להודיעך כחו\u0004 של \u0003ר' יהודה\u0004 שדנו דווקא במקרה זה להראות עד כמה מחמיר הוא,","שלדעתו \u0003אפילו דברים שטעונין ברכה לאחריהן במקומן,\u0004 ובודאי יחזרו לברך שם \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003הניחו מקצת חברים. אבל לא הניחו מקצת חברים, כשהן יוצאין — טעונין ברכה למפרע, וכשהן חוזרין — טעונין ברכה לכתחלה.\u0004 אבל חכמים מקילים ואומרים שאין צורך לברך בשינוי מקום אפילו בדברים שאין טעונים ברכה במקומם.","ומעירים עוד: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב חסדא: חברים שהיו מסובין\u0004 יחד \u0003לשתות יין, ועקרו רגליהן\u0004 ממקומם ללכת למקום אחר, \u0003וחזרו\u0004 אחר כך למקומם \u0003— אין צריכין\u0004 לחזור ו\u0003לברך.\u0004 ויין הוא מן הדברים החשובים שמברכים אחריהם במקומם, ולמדנו איפוא מכאן במפורש כדעת רב חסדא האומר שדברים שצריכים ברכה במקומם, אם עקר ממקומו וחזר, אין צורך לחזור ולברך עליהם בשנית.","ומעתה אנו חוזרים לדיני הפסקה בסעודה לצורך קידוש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בני חבורה שהיו מסובין\u0004 יחד ובתוך סעודתם \u0003קדש עליהן היום\u0004 (יום השבת) — \u0003מביאין לו\u0004 לאחד מהם \u0003כוס של יין ואומר עליו קדושת היום,\u0004 ומביאים לו כוס \u0003שני\u0004 ו\u0003אומר עליו\u0004 מיד \u0003ברכת המזון\u0004 שמפסיקים סעודתם של חול, אלו \u0003דברי ר' יהודה\u0004 הסבור כי מפסיקים לקידוש היום בשבת. \u0003ר' יוסי אומר: אוכל והולך\u0004 עד שיגמור סעודתו אפילו \u0003עד שתחשך.\u0004"],["\u0003גמרו\u0004 סעודתם, לדעת ר' יוסי מביא שני כוסות, \u0003כוס ראשון מברך עליו ברכת המזון והשני אומר עליו קדושת היום.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 צריכים שני כוסות? \u0003ונימרינהו לתרוייהו אחדא כסא\u0004 \u0005[ושיאמר את שתיהן\u0006 את ברכת המזון והקידוש \u0005על כוס אחת]!\u0006","\u0003אמר רב הונא אמר רב ששת:\u0004 הלכה היא ש\u0003אין אומרים שתי קדושות\u0004 (שתי מצוות, קידוש היום וברכת המזון) \u0003על כוס אחד.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]?\u0006 \u0003אמר רב נחמן בר יצחק: לפי שאין עושין מצות חבילות חבילות.\u0004 שהעושה כמה מצוות יחד כעין חבילה, נראה כאילו חפץ להיפטר מהם ולסיימן במהרה.","ושואלים: \u0003ולא,\u0004 וכי אין עושים כן? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לביתו במוצאי שבת מברך על היין\u0004 \"בורא פרי הגפן\" \u0003ועל המאור\u0004 (על הנר) \"בורא מאורי האש\", \u0003ועל הבשמים \"\u0004בורא מיני בשמים\", \u0003ואחר כך אומר הבדלה על הכוס. ואם אין לו אלא כוס אחד\u0004 של יין \u0003מניחו לאחר המזון\u0004 ומברך עליו ברכת המזון \u0003ומשלשלן\u0004 את כל שאר הברכות הללו \u0003כולן לאחריו.\u0004 משמע שגם מברך על המזון וגם מבדיל על כוס אחת בבת אחת! ומשיבים: מכאן אין ראיה, \u0003אין לו שאני\u0004 \u0005[שונה],\u0006 ובשעת הדחק מוטב שיברך כשיין לפניו, אבל כשיש לו שתי כוסות יין — יברך על כוס אחת ויקדש על השניה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יום טוב שחל להיות אחר השבת\u0004 (במוצאי שבת), שמן הסתם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 יין, ובכל זאת \u0003אמר רב\u0004 שסדר הברכות על הכוס הוא \u0003יקנ\"ה\u0004 — יין (\"בורא פרי הגפן\"), קידוש של חג, נר (\"מאורי האש\"), הבדלה לשבת, הרי שעושים קידוש והבדלה על כוס אחת!","\u0003אמרי\u0004 \u0005[אומרים\u0006 בדחיה\u0005]:\u0006 \u0003מ\u0004כיון ש\u0003לא אמר\u0004 ברכת \u0003זמן,\u0004 שלא מנה גם ברכת \"שהחיינו\" בין ברכות אלה \u0003מכלל\u0004 ש\u0003בשביעי של פסח עסקינן\u0004 \u0005[אנו עוסקים]\u0006 כאן, שכן זהו יום טוב יחיד שאין צריכים לומר בו \"שהחיינו\", וכיון שכך אפשר לומר ש\u0003כל מאי דהוה ליה אכיל ליה\u0004 \u0005[מה שהיה לו\u0006 בביתו \u0005אכלו\u0006 כבר\u0005]\u0006 ואין לו כבר יין כראוי לשני כוסות ולכן מברך הכל על כוס אחת.","ושוב מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יום טוב ראשון\u0004 שחל במוצאי שבת \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 מן הסתם עדיין שתי כוסות יין \u0003ואמר אביי\u0004 שסדר הברכות על הכוס במקרה זה הוא כסדר \u0003יקזנ\"ה\u0004 — יין, (\"בורא פרי הגפן\"), קידוש של חג, זמן (\"שהחיינו\"), נר הבדלה לשבת, \u0003ורבא אמר:\u0004 הסדר הוא \u0003יקנה\"ז\u0004 — יין, קידוש, נר, הבדלה, זמן, ומכל מקום לדעת שניהם אף שנחלקו בסדר הברכות הרי שעושים קידוש והבדלה על כוס יין אחת.","\u0003אלא\u0004 עלינו לדחות את ההסבר הקודם, ולומר: \u0003הבדלה וקידוש חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 והוא ענין הגדרת והבלטת קדושה שבימים מיוחדים. \u0003ברכת המזון וקידוש תרי מילי נינהו\u0004 \u0005[שני דברים\u0006 נבדלים \u0005הם]\u0006 והאומרם על כוס אחת נראה כמצרף מצוות שאינן שייכות זו לזו משום שרצונו להיפטר מהן.","\u0003גופא\u0004 \u0005[גוף\u0006 הדבר\u0005]\u0006, כיון שהוזכרה בעיית סדר ברכות בקידוש של יום טוב החל אחר השבת, דנים בענין לגופו. \u0003יום טוב שחל להיות אחר השבת רב אמר:\u0004 הסדר הוא \u0003יקנ\"ה —\u0004 יין, קידוש, נר, הבדלה. שתחילה גומר סדר הקידוש ואחר כך סדר הבדלה. \u0003ושמואל אמר:\u0004 הסדר הוא \u0003ינה\"ק\u0004 — יין, נר, הבדלה, קידוש. שתחילה גומר כל סדר הבדלה ואחר כך קידוש."],["\u0003ורבה אמר:\u0004 הסדר צריך להיות \u0003יהנ\"ק\u0004 — יין, הבדלה, נר, קידוש. ברכת יין תחילה, אחריה הבדלה וברכת הנר, וקידוש לבסוף. \u0003ולוי אמר:\u0004 הסדר הוא \u0003קני\"ה —\u0004 קידוש, נר, יין, הבדלה. \u0003ורבנן אמרי\u0004 \u0005[וחכמים אמרו]:\u0006 הסדר הוא \u0003קינ\"ה\u0004 — קידוש, יין, נר, הבדלה. \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא אמר:\u0004 הסדר הוא \u0003נקי\"ה\u0004 — נר, קידוש, יין, הבדלה. והחכם \u0003מרתא אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע: ניה\"ק\u0004 — נר, יין, הבדלה, קידוש, הבדלה.","ועוד בענין זה \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל,\u0004 אבא בן אבא, מכתב שאלה \u0003לרבי: ילמדנו רבינו, סדר הבדלות היאך,\u0004 כשחל יום טוב במוצאי שבת. \u0003שלח ליה\u0004 \u0005[לו]\u0006 רבי בתשובה: \u0003כך אמר ר' ישמעאל בר ר' יוסי שאמר משום אביו שאמר משום\u0004 (משמו) של \u0003ר' יהושע בן חנניה\u0004 הסדר הוא: \u0003נהי\"ק\u0004 — נר, הבדלה, יין, קידוש.","ומסבירים, \u0003אמר ר' חנינא: משל\u0004 שיש בו להסביר את שיטת \u0003ר' יהושע בן חנניה למלך שיוצא\u0004 מן העיר \u0003ואפרכוס\u0004 (השר הממונה על המחוז) \u0003נכנס,\u0004 שמידת דרך ארץ היא שבתחילה \u0003מלוין את המלך\u0004 מפני כבודו כדי להפרד ממנו \u0003ואחר כך יוצאים לקראת אפרכוס,\u0004 לקבל פניו. וכמו כן יש להקדים את סדר ההבדלה שהיא פרידה מן השבת ולבסוף קידוש של יום טוב שקדושתו ומעלתו אינה כשל שבת.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הלכה זו, ומה נפסק הלכה למעשה? אף בכך נחלקו אמוראים, שאמנם הסכימו לקבל להלכה את שיטת רב שבאופן עקרוני קידוש קודם להבדלה, אבל כיון שלא גלה דעתו מה עושים ברוב ימים טובים שיש להוסיף בהם גם ברכת \"זמן\", \u0003אביי אמר:\u0004 הסדר הוא \u0003יקזנ\"ה\u0004 — יין (\"בורא פרי הגפן\"), קידוש על החג, זמן (\"שהחיינו\") על החג, נר (\"בורא מאורי האש\"), והבדלה. \u0003ורבא אמר:\u0004 הסדר הוא \u0003יקנה\"ז\u0004 — יין, קידוש, נר, הבדלה, זמן. ומסכמים: \u0003והילכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004שיטת \u0003רבא\u0004 בענין זה.","בנושא זה של הבדלה מסופר: \u0003רב הונא בר יהודה איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא, אייתו לקמייהו\u0004 \u0005[הביאו לפניהם]\u0006 לאחר יציאת השבת \u0003מאור\u0004 (נר) \u0003ובשמים. בריך\u0004 \u0005[ברך]\u0006 \u0003רבא\u0004 על ה\u0003בשמים ברישא\u0004 \u0005[בראש]\u0006 \u0003והדר\u0004 \u0005[ואחר כך]\u0006 על ה\u0003מאור. אמר ליה\u0004 \u0005[לו]\u0006 רב הונא בר יהודה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בין\u0004 לשיטת \u0003בית שמאי ובין\u0004 לשיטת \u0003בית הלל\u0004 שנחלקו בסדרים אלה סבורים כי \u0003מאור ברישא\u0004 \u0005[בראש]\u0006 \u0003והדר\u0004 \u0005[ו\u0006רק \u0005אחר כך]\u0006 מברך על ה\u0003בשמים.\u0004","\u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003היא\u0004 ההלכה שבה נתפרש דבר זה, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים:\u0004 כשצריך לומר גם ברכת המזון וגם הבדלה ויש לו כוס יין אחת בלבד, סדר הברכות הוא \u0003נר, ו\u0004ברכת ה\u0003מזון, בשמים, והבדלה. ובית הילל אומרים: נר, ובשמים, ו\u0004ברכת ה\u0003מזון, והבדלה.\u0004 ומכל מקום שניהם מסכימים כי נר תחילה!","\u0003עני\u0004 \u0005[ענה]\u0006 \u0003רבא בתריה\u0004 \u0005[אחריו]\u0006 \u0003ואמר\u0004 כמשלים את דבריו: משנה זו כ\u0003דברי ר' מאיר. אבל ר' יהודה אומר: לא נחלקו בית שמאי ובית הילל על המזון שהוא בתחלה ועל הבדלה שהיא בסוף,\u0004","\u0003על מה נחלקו — על המאור ועל הבשמים. בית שמאי אומרים:\u0004 ברכת \u0003מאור\u0004 תחילה \u0003ואחר כך\u0004 ברכת \u0003בשמים, ובית הילל אומרים:\u0004 ברכת \u0003בשמים\u0004 תחילה \u0003ו\u0004רק \u0003אחר כך\u0004 ברכת \u0003מאור. ואמר ר' יוחנן: נהגו העם כבית הילל ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' יהודה,\u0004 וכך נהג רבא.","ועוד בדיני קביעות לסעודה ולברכה. מסופר: \u0003רב יעקב בר אבא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא\u0004 לסעודת שבת, \u0003חזייה דבריך\u0004 \u0005[ראהו ש\u0006הוא \u0005מברך]\u0006 \u0003\"בורא פרי הגפן\" אכסא קמא\u0004 \u0005[על הכוס הראשונה]\u0006 בתוך הסעודה, \u0003והדר בריך אכסא דברכתא, ואישתי\u0004 \u0005[וחזר וברך על כוס ברכת\u0006 המזון, \u0005ושתה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003למה לך כולי האי\u0004 \u0005[כל זה]\u0006 לברך עוד ברכה נוספת? \u0003הא בריך לן מר חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005ברך לנו אדוני\u0006 על היין \u0005פעם אחת]\u0006 ובברכה ראשונה זו פטר כל יין ששותה לאחר מכן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי הוינן בי ריש גלותא הכי עבדינן\u0004 \u0005[כאשר היינו\u0006 סועדים \u0005בבית ראש הגולה כך היינו עושים]\u0006 משמע שכן הוא מנהג חכמים.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תינח בי ריש גלותא דהכי עביד\u0004 \u0005[נניח\u0006 ב\u0005בית ראש הגולה שכך עושים],\u0006 ש\u0003ספק מייתי לן\u0004 \u0005[מביא לנו]\u0006 יין נוסף \u0003ספק לא מייתי לן\u0004 \u0005[מביא לנו],\u0006 שאנו תלויים בדעת בעל הבית. וכיון שכך, כל כוס וכוס צריך לברך עליה לעצמה. \u0003הכא, הא מנח כסא קמן ודעתן עילויה\u0004 \u0005[כאן, הלא מונחת הכוס לפנינו ודעתנו עליה\u0006 לשתותה\u0005]\u0006 לאחר המזון, ומה טעם לברך שנית? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא עבדי\u0004 \u0005[אני עשיתי]\u0006 \u0003כ\u0004שיטת \u0003תלמידי רב,\u0004 כמסופר: \u0003רב ברונא ורב חננאל תלמידי רב הוו יתבי בסעודתא\u0004 \u0005[היו יושבים\u0006 יחד \u0005בסעודה]\u0006"],["\u0003קאי עלייהו\u0004 \u0005[עמד עליהם\u0006 לשמשם\u0005]\u0006 \u0003רב ייבא סבא\u0004 \u0005[הזקן].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הב לן וניבריך\u0004 \u0005[הבה ונברך].\u0006 \u0003לסוף\u0004 שסיימו סעודתם התחרטו ו\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הב לן ונישתי\u0004 \u0005[הבה ונשתה]\u0006 עוד יין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב כיון דאמריתו הב לן וניבריך, איתסרא לכו למישתי\u0004 \u0005[שאמרתם הבה ונברך, נאסר לכם לשתות\u0006 עוד\u0005].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, \u0003דאסחיתו דעתייכו\u0004 \u0005[שהסחתם\u0006 את \u0005דעתכם]\u0006 מלשתות עוד. ולכן אם רצונכם לשתות יין לאחר מכן, יש לכם צורך לברך שנית \"בורא פרי הגפן\".","מסופר: \u0003אמימר ומר זוטרא ורב אשי הוו יתבי\u0004 \u0005[היו יושבים]\u0006 \u0003בסעודה, וקאי עלייהו\u0004 \u0005[ועמד עליהם\u0006 לשמשם\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, אמימר בריך על כל כסא וכסא\u0004 \u0005[ברך על כל כוס וכוס\u0006 של יין לחוד\u0005],\u0006 \u0003ומר זוטרא בריך אכסא קמא ואכסא בתרא\u0004 \u0005[בירך על כוס ראשונה\u0006 ששתה בתוך הסעודה \u0005ועל כוס האחרונה\u0006 ששתה לברכת המזון\u0005],\u0006 \u0003רב אשי בריך אכסא קמא, ותו\u0004 \u0005[ברך על הכוס הראשונה, ושוב]\u0006 \u0003לא בריך.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אחא בר רבא: אנן כמאן נעביד\u0004 \u0005[אנחנו כמי נעשה]?\u0006 שהרי ראינו שלוש דרכים בהלכה זו! \u0003אמימר אמר: נמלך אנא\u0004 \u0005[אני]\u0006 ואין זו הלכה כללית, משום שבשעת שתיית כוס ראשונה לא התכוון לשתות כוס נוספת, וכאשר שתה כוס אחרת היה זה משום שהתחרט, וכיון שהסיח דעתו מלשתות לאחר שתיית כוס ראשונה — חייב לברך שנית. \u0003מר זוטרא אמר: אנא דעבדי\u0004 \u0005[אני שעשיתי]\u0006 \u0003כ\u0004שיטת \u0003תלמידי רב,\u0004 שלאחר שמתכוננים לברך ברכת המזון, הרי זו הסחת דעת גמורה ושוב אין ברכה שבתוך המזון פוטרת יין שלאחר ברכת המזון.","\u0003ורב אשי אמר: לית הילכתא\u0004 \u0005[אין הלכה]\u0006 \u0003כ\u0004שיטת \u0003תלמידי רב,\u0004 והוכחה לדבר משיטת רב עצמו \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003יום טוב שחל להיות אחר השבת, ואמר רב:\u0004 סדר הקידוש הוא: \u0003יקנ\"ה —\u0004 יין, קידוש, נר, הבדלה. ונמצא שלמרות שעושה קידוש לאחר ברכת היין ומפסיק על ידי כך בין ברכה זו להבדלה אינו מתחייב שוב לברך על היין שלפני ההבדלה! ואם כן, הוא הדין גם לשתי כוסות יין, של קידוש ושל ברכת המזון, שאין צריך לברך בשנית על זו של ברכת המזון.","ודוחים: \u0003ולא היא, התם\u0004 \u0005[שם]\u0006 כאשר התכונן לברך על המזון כבר \u0003עקר דעתיה ממשתיא\u0004 \u0005[דעתו מלשתות\u0006 עוד\u0005],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בקידוש והבדלה \u0003לא עקר דעתיה ממשתיא\u0004 \u0005[עקר דעתו מלשתות].\u0006","לאחר פירוט זה של שיטת תלמידי רב חוזרים לסיפור המעשה ברב יעקב בר אבא שביקר את רבא. \u0003כי מטא לאבדולי, קם שמעיה ואדליק אבוקה משרגא\u0004 \u0005[כאשר הגיע\u0006 הזמן \u0005להבדיל עמד שמשו\u0006 של רבא \u0005והדליק אבוקה מן הנר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יעקב בר אבא: \u0003למה לך כולי האי\u0004 \u0005[כל זה],\u0006 \u0003הא מנחא שרגא\u0004 \u0005[הרי מונח הנר]\u0006 ויכול אתה לברך ברכת המאורות על הנר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שמעא מדעתיה דנפשיה קא עביד\u0004 \u0005[השמש מדעת עצמו עשה]\u0006 ולא שאל לדעתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יעקב: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שמיע ליה מיניה דמר\u0004 \u0005[היה שומע מאדוני]\u0006 שכן הלכה, \u0003לא הוה עביד\u0004 \u0005[היה עושה כן]\u0006 מדעת עצמו, ובודאי נהג כהוראותיך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: וכי \u0003לא סבר ליה מר\u0004 \u0005[סבור אדוני]\u0006 כמקובל כי \u0003אבוקה להבדלה — מצוה מן המובחר\u0004 היא ולכן הידר מטעם זה להדליק אבוקה.","\u0003פתח\u0004 רבא \u0003ואמר\u0004 בנוסח ההבדלה: \u0003\"המבדיל בין קודש לחול בין אור לחשך בין ישראל לעמים בין יום השביעי לששת ימי המעשה\" אמר ליה\u0004 \u0005[לו]\u0006 רב יעקב: \u0003למה לך כולי האי\u0004 \u0005[כל זה]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב\u0004 אמירת \u0003\"המבדיל בין קודש לחול\"\u0004 בלבד \u0003זו היא הבדלתו של ר' יהודה הנשיא,\u0004 ואם כן מדוע לא תסתפק בכך?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא כהא סבירא לי\u0004 \u0005[אני כ\u0006שיטה \u0005זו סבור אני]\u0006 ש\u0003אמר ר' אלעזר אמר רב אושעיא: הפוחת\u0004 ומקצר בנוסח ההבדלה \u0003לא יפחות משלש\u0004 הבדלות \u0003והמוסיף\u0004 ומאריך בהבדלות רבות יותר (כנוסחות שלפנינו) \u0003לא יוסיף על שבע. אמר ליה\u0004 \u0005[לו]\u0006 רב יעקב לרבא:"],["\u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003לא תלתא\u0004 \u0005[שלוש]\u0006 \u0003אמר ולא שבע אמר,\u0004 שהרי אמר ארבע! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איברא\u0004 \u0005[באמת]\u0006 אין הדבר כן; \u0003\"בין יום השביעי לששת ימי המעשה\"\u0004 איננו הבדלה לעצמה, אלא \u0003מעין חתימה היא,\u0004 כפי ש\u0003אמר רב יהודה אמר שמואל: המבדיל צריך שיאמר מעין\u0004 נוסח \u0003חתימה\u0004 של הברכה בסופה, \u0003סמוך לחתימתו\u0004 להבליט את הקשר בין החתימה והברכה. \u0003ופומבדיתאי אמרי\u0004 \u0005[ו\u0006חכמי \u0005פומבדיתא אומרים]\u0006 \u0003מעין\u0004 נוסח \u0003פתיחתן סמוך לחתימתן.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 למעשה \u0005ביניהם],\u0006 שלכאורה גם הפתיחה וגם החתימה הם כרגיל באותו נושא, ומה ההבדל בין נוסח זה לזה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003יום טוב שחל להיות אחר השבת\u0004 שבנוסח ההבדלה הנאמר במוצאי שבת שהוא ליל יום טוב, \u0003חתמינן\u0004 \u0005[חותמין אנו]\u0006 בסופה \u0003\"\u0004המבדיל \u0003בין קודש לקודש\",\u0004","\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לחזור \u0003מעין פתיחתן סמוך לחתימתן,\u0004 לשיטתו \u0003לא בעי למימר\u0004 \u0005[אינו צריך לומר]\u0006 \u0003\"בין קדושת שבת לקדושת יום טוב הבדלת\"\u0004 שהרי בפתיחת ברכה זו אומר רק הבדלה בין קודש לחול. \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שצריך לחזור \u0003מעין חתימתן סמוך לחתימתן,\u0004 לשיטתו \u0003בעי למימר\u0004 \u0005[צריך לומר]\u0006 \u0003\"בין קדושת שבת לקדושת יום טוב הבדלת\".\u0004","חוזרים אנו ל \u0003גופא\u0004 \u0005[גוף]\u0006 אותה הלכה שהזכרנו. \u0003אמר ר' אלעזר אמר ר' אושעיא: הפוחת\u0004 במנין ההבדלות — \u0003לא יפחות משלש, והמוסיף — לא יוסיף על שבע.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מן התוספתא: \u0003אומר הבדלות במוצאי שבתות ובמוצאי ימים טובים ובמוצאי יום הכפורים, ובמוצאי שבת ליום טוב ובמוצאי יום טוב לחולו של מועד, אבל לא\u0004 יבדיל בין \u0003מוצאי יום טוב לשבת\u0004 שקדושת השבת יתירה על קדושת יום טוב. \u0003הרגיל\u0004 ובקי בברכות \u0003אומר הרבה ושאינו רגיל אומר אחת.\u0004 משמע שבאופן עקרוני אפשר לומר גם פחות משלש ויותר על שבע.","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, ש\u0003אמר ר' יוחנן: בנן של קדושים אומר\u0004 רק הבדלה \u0003אחת,\u0004 אבל \u0003נהגו העם לומר שלש.\u0004 ושואלים: \u0003מאן ניהו\u0004 \u0005[מיהו זה]\u0006 המכונה \u0003\"בנן של קדושים\"?\u0004 ומשיבים: \u0003ר' מנחם בר סימאי\u0004 הוא. \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קראו לו]\u0006 \u0003\"בנן של קדושים\"\u0004 משום ש\u0003לא איסתכל בצורתא דזוזא\u0004 \u0005[היה מסתכל\u0006 אף \u0005בצורה שעל המטבע]\u0006 כי בצורות אלה יש לפעמים דמויות עבודה זרה ודמויות אסורות אחרות, ולכן לא רצה להסתכל בהן. מסופר, כי \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר אידי: חנניא אחי אומר\u0004 שאומרים הבדלה \u0003אחת\u0004 בלבד, ומסכמים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006","\u0003אמר ר' יהושע בן לוי: המבדיל צריך שיאמר מעין הבדלות האמורות בתורה\u0004 במפורש, ולא יוסיף עליהן הבדלות שאינן כתובות. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003סדר הבדלות היאך? אומר: \"המבדיל בין קודש לחול, בין אור לחושך בין ישראל לעמים, ובין יום השביעי לששת ימי המעשה, בין טמא לטהור, בין הים לחרבה, בין מים העליונים\u0004 שמעל לרקיע \u0003למים התחתונים\u0004 שמתחת לרקיע, \u0003בין כהנים ללוים וישראלים\",\u0004 והוא נוסח ההבדלה הארוך. שיש בו שבע הבדלות.","\u0003וחותם\u0004 ברכה זו \u0003ב\"סדר בראשית\"\u0004 (\"ברוך עושה סדר בראשית\", או \"ברוך סודר בראשית\"). \u0003ואחרים אומרים:\u0004 חותם \u0003ב\"יוצר בראשית\". ר' יוסי בר יהודה אומר: חותם \"מקדש ישראל\". ואם איתא\u0004 \u0005[ואם יש]\u0006 תוקף להלכה זו של ר' יהושע בן לוי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"בין הים לחרבה\" לא כתיבא ביה\u0004 \u0005[כתובה בו]\u0006 לשון \u0003\"הבדלה\"\u0004 שהרי אין לנו כתוב האומר \"המבדיל בין הים לחרבה\"! ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן\u0004 את ההבדלה \u0003\"בין הים לחרבה\".\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלא ההבדלה \u0003\"בין יום השביעי לששת ימי המעשה\" נמי\u0004 \u0005[גם כן]\u0006 איננה נמנית במנין ההבדלות? כפי שאמרנו שהרי אינה אלא חזרה \u0003מעין חתימה הוא,\u0004 ואם כן \u0003בצר חדא\u0004 \u0005[חסרה\u0006 הבדלה \u0005אחת]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 \u0003שבע!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ההבדלה בין \u0003כהנים לוים וישראלים תרי מילי נינהו\u0004 \u0005[שני דברים הם]\u0006 ושתי הבדלות, ש\u0003בין לוים לישראלים\u0004 יש הבדלה אחת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בעת ההיא הבדיל ה' את שבט הלוי\u0004 לשאת את ארון ברית ה'\u0003\"\u0004 (דברים י, ח), ואילו \u0003בין הכהנים ללוים\u0004 יש הבדלה נוספת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בני עמרם אהרן ומשה ויבדל אהרן להקדישו קדש קדשים\u0004 הוא ובניו עד עולם\u0003\"\u0004 (דברי הימים א' כג, יג).","ושואלים: כיון שרבו הדעות בחתימת ההבדלה \u0003מחתם מאי חתים\u0004 \u0005[לחתום מהו חותם]?\u0006 \u0003רב אמר:\u0004 חותם \u0003\"מקדש ישראל\", ושמואל אמר:\u0004 חותם \u0003\"המבדיל בין קודש לחול\".\u0004 ומוסיפים: \u0003לייט עלה אביי\u0004 \u0005[קלל,\u0006 כעס, \u0005עליו אביי]\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יוסף אהא\u0004 \u0005[על מי\u0006 שעושה כשיטתו \u0005זו]\u0006 של \u0003רב,\u0004 שאין לומר כן כלל.","\u0003תנא משמיה\u0004 \u0005[שנה משמו]\u0006 של \u0003ר' יהושע בן חנניא: כל החותם\u0004 בנוסח \u0003\"מקדש ישראל והמבדיל בין קודש לחול\"\u0004 בהבדלה \u0003מאריכין לו ימיו ושנותיו.\u0004"],["ומוסיפים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו]\u0006 ופוסקים כשמואל.","מסופר: \u0003עולא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לפומבדיתא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]:\u0006 \u0003זיל אמטי ליה\u0004 \u0005[לך הבא לו\u0006 לעולא\u0005]\u0006 \u0003כלכלה\u0004 (סל) \u0003דפירי\u0004 \u0005[של פירות]\u0006 כמתנה, \u0003ו\u0004בתוך כך \u0003חזי היכי אבדיל\u0004 [\u0005ראה כיצד הוא מבדיל].\u0006 \u0003לא אזל\u0004 \u0005[הלך]\u0006 רב יצחק בעצמו, אלא \u0003שדר ליה\u0004 \u0005[שלח אותו]\u0006 את \u0003אביי\u0004 שהיה אז תלמיד קטן, שילך בשליחותו. \u0003כי אתא\u0004 \u0005[כאשר בא,\u0006 חזר\u0005]\u0006 \u0003אביי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי\u0004 \u0005[איך]\u0006 \u0003אמר\u0004 עולא את לשון ההבדלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"ברוך המבדיל בין קודש לחול\" אמר, ותו\u0004 \u0005[ויותר]\u0006 \u0003לא.\u0004","\u0003אתא לקמיה דאבוה\u0004 \u0005[בא\u0006 רב יצחק \u0005לפני אביו\u0006 רב יהודה\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003היכי\u0004 \u0005[איך]\u0006 \u0003אמר\u0004 עולא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא אזלי\u0004 \u0005[הלכתי]\u0006\u0003, אנא שדריתיה\u0004 \u0005[אני שלחתי]\u0006 את \u0003אביי, ואמר לי\u0004 שאמר \u0003\"המבדיל בין קודש לחול\".\u0004 כעס רב יהודה ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רברבנותיה דמר, וסררותיה דמר, גרמא ליה למר דלא תימא שמעתיה מפומיה\u0004 \u0005[רברבנותו של אדוני, ושררותו של אדוני גרמה לו לאדוני שלא תאמר שמועה מפיו]\u0006 שאילו הלכת בעצמך היו מוסרים את ההלכה בשמך, שאתה הוא שמסרת הלכה זו בשם עולא, ועל ידי עצלות וגאוה גרמת שתמסר ההלכה בשם אביי.","על מנהגו של עולא \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא: \u0003כל הברכות כולן פותח בברוך וחותם בהן בברוך, חוץ מברכת המצות\u0004 הברכה שנאמרת לפני עשיית המצוה , \u0003וברכת\u0004 הנאה מן \u0003הפירות, וברכה הסמוכה לחבירתה\u0004 בתוך סדר התפילה (כגון ברכות שמונה עשרה) \u0003וברכה אחרונה שבקרית שמע,\u0004","\u0003שיש מהן פותח בברוך ואין חותם בברוך\u0004 כברכת המצוות והפירות \u0003ויש מהן שחותם בברוך ואין פותח בברוך\u0004 כגון ברכה הסמוכה לחברתה ויוצאת מן הכלל ברכת \u0003\"הטוב והמטיב\"\u0004 שבתוך ברכת המזון שאף שהיא סמוכה לברכות אחרות \u0003פותח\u0004 בה \u0003בברוך ואינו חותם בברוך\u0004"],["\u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003ל\u0004שיטת \u0003עולא\u0004 שפתח בברוך ולא חתם בברוך! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003עולא: הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003כברכת המצות דמיא\u0004 \u0005[נחשבת]\u0006 ואינה צריכה חתימה, כי אף \u0003ברכת המצות מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין חותמים בה \u0003משום דהודאה\u0004 בלבד \u0003היא\u0004 ואין בה דברים שלא מעניינה אלא הודאה בלבד ואין בה הפסק של שום דבר אחר, כגון: תחינה או ריצוי, ולכן די בפתיחה אפילו בלא חתימה . \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 ההבדלה ברכת \u0003הודאה\u0004 בלבד \u0003היא.\u0004","מסופר: \u0003רב חנניא בר שלמיא ו\u0004שאר \u0003תלמידי רב, הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה]\u0006 ערב שבת סמוך לחשיכה, \u0003וקאי עלייהו\u0004 \u0005[והיה עומד עליהם\u0006 ומשמשם\u0005]\u0006 \u0003רב המנונא סבא\u0004 \u0005[הזקן].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל חזי אי מקדיש יומא ונפסיק וניקבעיה לשבתא\u0004 \u0005[לך וראה אם קדש היום,\u0006 כלומר אם החשיך, \u0005ונפסיק\u0006 בעקירת השלחן \u0005ונקבע את סעודתנו לשם שבת]\u0006 \u0003אמר להו\u0004 \u0005[ להם ]:\u0006 \u0003לא צריכיתו\u0004 \u0005[אין אתם צריכים\u0006 לכך\u0005]\u0006 \u0003שבתא קבעה נפשה\u0004 \u0005[השבת קובעת לעצמה]\u0006 שעם כניסת השבת מה שאוכלים אז נחשב ממילא סעודת שבת ואין צורך בפעולה נוספת מיוחדת שתבטא הפסקה.","ש\u0003אמר רב: כשם שהשבת קובעת למעשר\u0004 שבכל השנה אכילת עראי אינה חייבת במעשר ואילו בשבת אפילו אכילת עראי צריך להפריש ממנה מעשר, משום שגם אם אינו מתכוון במפורש לכך, נחשבת הארוחה כארוחת קבע, \u0003כך קובעת\u0004 ה\u0003שבת לקידוש\u0004 שאין להמשיך עוד לאכול עד שיקדש, לאחר שכבר נכנסה השבת. ומכאן ראיה שמשחשיכה הריהי נחשבת ונקבעת מאליה כסעודת שבת.","\u0003סבור מינה\u0004 \u0005[סברו\u0006 השומעים \u0005מ\u0006הלכה \u0005זו]\u0006 \u0003כי היכי דקבעה\u0004 \u0005[כפי שהיא קובעת]\u0006 \u0003לקידוש כך קבעה להבדלה\u0004 ועם יציאת השבת שוב אין הסעודה נחשבת כסעודת שבת וחייב להפסיק ולהבדיל, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב עמרם: הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: לקידוש קובעת ולא להבדלה קובעת.\u0004","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים \u0003לענין מיפסק\u0004 \u0005[הפסקה]\u0006 ש\u0003לא מפסקינן\u0004 \u0005[מפסיקים],\u0006 ואם התחילו בסעודה ביום השבת אין צורך להפסיק משחשיכה. \u0003אבל אתחולי\u0004 \u0005[להתחיל]\u0006 \u0003לא מתחלינן\u0004 \u0005[מתחילים]\u0006 לאכול לאחר שחשיכה ואפילו לא עשה עדיין הבדלה. ומעירים: \u0003ומיפסק נמי\u0004 \u0005[להפסיק גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 לענין \u0003אכילה\u0004 שהיא דבר חשוב, שאין מפסיקים כיון שכבר התחיל \u0003אבל בשתיה\u0004 שאינה דבר חשוב \u0003— לא,\u0004 וצריך להפסיק אם התחיל לשתות לפני יציאת השבת.","\u0003ושתיה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאסור להתחיל בשתיה משחשיכה \u0003אלא בחמרא ושיכרא\u0004 \u0005[ביין ושכר]\u0006 שהם חשובים, \u0003אבל מיא\u0004 \u0005[מים] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, ויכול להתחיל לשתות מים אף אחר יציאת השבת אפילו קודם הבדלה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה אחרונה זו על דעתו של \u0003רב הונא,\u0004 ש\u0003רב הונא חזייה לההוא גברא\u0004 \u0005[ראה אדם אחד]\u0006 ש\u0003שתה מיא\u0004 \u0005[מים]\u0006 \u0003קודם הבדלה\u0004 לאחר יציאת השבת. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003לא מיסתפי מר\u0004 \u0005[חושש אדוני]\u0006 \u0003מ\u0004מחלת ה\u0003אסכרה? דתנא משמיה\u0004 \u0005[ש\u0006כן \u0005שנינו משמו]\u0006 של \u0003ר' עקיבא: כל הטועם כלום\u0004 (משהו) \u0003קודם שיבדיל — מיתתו ב\u0004מחלת ה\u0003אסכרה.\u0004 ואולם מעירים כי \u0003רבנן דבי\u0004 \u0005[חכמי בית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי לא קפדי אמיא\u0004 \u0005[היו מקפידים על המים]\u0006 שלא לשתות ונמנעו רק ממשקאות חשובים.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבינא מרב נחמן בר יצחק: מי שלא קידש בערב שבת מהו שיקדש והולך כל היום כולו,\u0004 או שמא כל שלא קידש בזמנו שוב אינו מקדש? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003מדאמרי\u0004 \u0005[מ\u0006מה \u0005שאמרו]\u0006 \u0003בני ר' חייא: מי שלא הבדיל במוצאי שבת מבדיל והולך כל השבת\u0004 (השבוע) \u0003כולו\u0004 נלמד, כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מי שלא קידש בערב שבת מקדש והולך כל היום כולו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבינא מהתוספתא: \u0003לילי שבת ולילי יום טוב יש בהן קדושה\u0004 (קידוש) \u0003על הכוס ויש בהן הזכרה\u0004 של קדושת היום בתוך \u0003ברכת המזון בשבת —\u0004 \"רצה והחליצנו\" וביום טוב — \"יעלה ויבוא\"\u0003, שבת ויום טוב\u0004 ביום \u0003אין בהם קדושה\u0004 (קידוש) \u0003על הכוס ויש בהם הזכרה\u0004 קדושת היום בתוך \u0003ברכת המזון,\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003מי שלא קידש בערב שבת מקדש והולך כל היום כולו,\u0004 אם כן \u0003שבת ויום טוב נמי\u0004 \u0005[גם כן]\u0006 \u0003משכחת להו\u0004 \u0005[מוצא אתה אותם]\u0006 במקרים מסויימים ש\u0003יש בהם קדושה על הכוס, דאי\u0004 \u0005[שאם]\u0006 \u0003לא קידש מאורתא\u0004 \u0005[מהערב]\u0006 \u0003מקדש למחר! אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \"\u0003דאי\"\u0004 \u0005[\"שאם\"]\u0006 \u0003לא קתני\u0004 \u0005[שנינו],\u0006 כלומר אין ברייתא זו עוסקת במקרה נדיר שאירע רק אם שינה מן הרגיל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממקור אחר: \u0003כבוד יום\u0004 השבת \u0003וכבוד לילה — כבוד יום קודם. ואם אין לו אלא כוס\u0004 יין \u0003אחד\u0004 — \u0003אומר עליו\u0004"],["\u0003קידוש היום\u0004 בכניסת השבת, \u0003מפני שקידוש היום קודם\u0004 בחשיבות \u0003לכבוד יום וכבוד לילה. ואם איתא\u0004 \u0005[יש]\u0006 בסיס לדעתך שאפשר להשלים את קידוש היום במשך כל יום השבת — \u0003לישבקיה\u0004 \u0005[שיניח]\u0006 את הכוס \u0003עד למחר, וליעביד ביה תרתי\u0004 \u0005[ויעשה בה שני דברים]\u0006 שיעשה קידוש של שבת, וגם יכבד בו את יום השבת בשתיית יין! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חביבה מצוה בשעתה,\u0004 ואם יכול אדם לקיים מצוה מיד בשעה שנתחייב בה ראוי לו לחבבה ולהקדימה.","ומקשים: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 ש\u0003חביבה מצוה בשעתה? והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנכנס לביתו במוצאי שבת — מברך על היין ועל המאור ועל הבשמים ואחר כך אומר הבדלה על הכוס. ואם אין לו אלא כוס אחד\u0004 של יין ורוצה לאכול ולברך ברכת המזון על היין \u0003מניחו עד לאחר המזון ומשלשלן כולן,\u0004 הן ברכת המזון והן ברכות ההבדלה, \u0003לאחריו\u0004 לאחר ברכת המזון ומכאן נלמד כי \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 במקרה כזה \u0003חביבה מצוה בשעתה,\u0004 שיעשה מיד הבדלה ולא ימתין לסיים סעודתו ולברך ברכת המזון על היין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בענוה: \u0003אנא לא חכימאה אנא, ולא חוזאה אנא, ולא יחידאה אנא, אלא גמרנא וסדרנא אנא, וכן מורין בבי מדרשא כוותי\u0004 \u0005[אני לא חכם אני, ולא מגיד אני, ולא \"יחיד\"\u0006 חשוב \u0005אני, אלא שונה אני ומסדר אני\u0006 דברי הלכה, \u0005וכן מורים בבית המדרש כמותי]:\u0006 \u0003שאני לן בין עיולי יומא לאפוקי יומא\u0004 \u0005[שונה לנו\u0006 להלכה \u0005בין הכנסת היום,\u0006 השבת, \u0005להוצאת היום].\u0006 וטעם הדבר: \u0003עיולי יומא\u0004 \u0005[בכניסת היום]\u0006 \u0003כל כמה דמקדמינן ליה\u0004 \u0005[שמקדימים אנו אותו\u0006 בקידוש\u0005]\u0006 \u0003עדיף, ומחבבינן ליה\u0004 \u0005[ומחבבים אנו אותו]\u0006 על ידי כך, ומראים שחפצנו בו. \u0003אפוקי יומא\u0004 \u0005[הוצאת היום] —\u0006 \u0003מאחרינן ליה, כי היכי\u0004 \u0005[מאחרים אנו אותה, כדי]\u0006 ש\u0003לא ליהוי עלן כטונא\u0004 \u0005[יהיה\u0006 יום השבת נראה \u0005עלינו כמשא]\u0006 שאני שמחים לפורקו מעלינו.","ומעירים: \u0003שמע מינה\u0004 \u0005[\u0006יכול אתה \u0005ללמוד ממנה]\u0006 \u0003מיהא מתניתא\u0004 \u0005[מברייתא זו]\u0006 שהבאנו \u0003תמני\u0004 \u0005[שמונה\u0006 דברים\u0005]\u0006 ומפרטים: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 מתוך מה שנאמר שהנכנס לביתו במוצאי שבת מברך על היין... ואחר כך אומר הבדלה, והרי מן הסתם כבר הבדיל ב\"אתה חוננתנו\", אלא ודאי שגם \u0003המבדיל בתפלה\u0004 אף על פי שאמר בה \"אתה חוננתנו\" \u0003צריך שיבדיל\u0004 שנית \u0003על הכוס.\u0004","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ממה שנאמר \"המברך על היין\": \u0003ברכה,\u0004 ברכת המזון, \u0003טעונה כוס. ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003כוס של ברכה צריך שיעור,\u0004 שאם לא כן היה יכול להבדיל, ולהשאיר מעט לצורך הברכה.","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003המברך\u0004 ברכה כל שהיא \u0003צריך שיטעום\u0004 ממה שמברך עליו, שאם לא כן הרי יכול לומר ברכת המזון על הכוס ולא לטעום ממנה ולאחר מכן יבדיל על אותה כוס. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 אם \u0003טעמו\u0004 את הכוס — \u0003פגמו\u0004 ושוב אינו ראוי לברכה. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 גם אם \u0003טעם\u0004 משהו אחרי יציאת השבת \u0003מבדיל\u0004 בכל זאת, ואין אומרים שכיון שאכל אינו צריך לעשות עוד הבדלה."],["\u0003ושמע מינה\u0004 \u0005[ולמד ממנה],\u0006 כי אם אין לאדם אלא כוס יין אחת — הריהו \u0003אומר שתי קדושות על כוס אחד,\u0004 שהרי מברך שתי ברכות שונות במהותן על אותה כוס. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה],\u0006 שמשנה זו כשיטת \u0003בית שמאי היא ואליבא\u0004 \u0005[ועל פי]\u0006 שיטת \u0003ר' יהודה\u0004 שהוא המסדר כך את סדר הברכות, תחילה על המאור ואחר כך על הבשמים.","\u0003רב אשי אמר:\u0004 אם נדקדק בדברים שאנו למדים מברייתא זו, יש להעיר כי \u0003טעמו — פגמו\u0004 וכן הענין ש\u0003כוס של ברכה צריך שיעור — חדא מילתא היא\u0004 \u0005[דבר אחד,\u0006 עיקרון אחד, \u0005הוא]\u0006 ואין למנותם כשני דברים.","\u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומרים אנו \u0003טעמו פגמו — משום\u0004 ש\u0003כוס של ברכה צריך שיעור\u0004 וכיון שטעמו — נחסר שיעורו ולכן הוא נפגם ולא מפני עצם הטעימה. ואם על אף הטעימה עדיין נותר בו שיעור — לא פגמו. אף שיש חכמים הסוברים, כי טעימה יש בה פגם מצד עצמה.","ומספרים, כי \u0003ר' יעקב בר אידי קפיד אחצבא פגימא\u0004 \u0005[היה מקפיד על כד פגום]\u0006 שלא לקדש על כד יין ששתו כבר ממנו. \u0003רב אידי בר שישא קפיד\u0004 \u0005[היה מקפיד]\u0006 \u0003אכסא פגימא\u0004 \u0005[כוס פגומה]\u0006 אפילו גדולה, \u0003מר בר רב אשי קפיד\u0004 \u0005[היה מקפיד]\u0006 \u0003אפילו אחביתא פגימתא\u0004 \u0005[על חבית פגומה]\u0006 ולא היה לוקח לקידוש אלא מחבית שלא נפתחה כלל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: על הנאמר בכתוב \u0003\"זכור את יום השבת לקדשו\"\u0004 (שמות כ, ח) כיצד מקיימים מצוה זו של זכירה — \u0003זוכרהו על היין\u0004 בקידוש. \u0003אין לי אלא\u0004 שעושים קידוש \u0003ביום,\u0004 שהרי נאמר בכתוב לשון \"יום\", \u0003בלילה מנין\u0004 שמקדשים? \u0003תלמוד לומר \"זכור את יום השבת לקדשו\"\u0004 שמשמעו — מזמן שקדש היום.","על קושיה אחרונה זו תוהים: \u0003\"בלילה מנין\"?\u0004 וכי זו שאלה? \u0003אדרבה, עיקר קדושא\u0004 \u0005[הקידוש]\u0006 \u0003בלילה הוא קדיש\u0004 \u0005[מקדש]\u0006 \u0003דכי קדיש —\u0004 שאת \u0003תחלת יומא בעי לקידושי\u0004 \u0005[היום צריך לקדש],\u0006 ולא יתכן שיקדש היום כאשר הוא כבר באמצע! \u0003ותו\u0004 \u0005[ועוד],\u0006 בהמשך אותה ברייתא נאמר: \u0003בלילה מנין — תלמוד לומר: \"זכור את יום\",\u0004 הרי ה\u0003תנא מיהדר אלילה\u0004 \u0005[חוזר\u0006 להביא ראיה \u0005ל\u0006חובת קידוש ב\u0005לילה]\u0006 \u0003וקא נסיב ליה קרא דיממא\u0004 \u0005[ומביא\u0006 כתירוץ \u0005פסוק של יום]?\u0006","ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש לתקן את הברייתא: \u0003\"זכור את יום השבת\"\u0004 כוונתו \u0003זוכרהו על היין בכניסתו, אין לי אלא\u0004 שזוכר אותו \u0003בלילה ביום מנין\u0004 שמצוה גם כן לעשות קידוש? \u0003תלמוד לומר: \"זכור את יום השבת\",\u0004 ומן ההדגשה \"יום\" למדים שגם ביום יש לחזור ולקדש.","ושואלים: בקידוש של \u0003יום מאי\u0004 \u0005[מה]\u0006 \u0003מברך\u0004 שהרי אינו יכול לקדש אז כבלילה! \u0003אמר רב יהודה:\u0004 מביא יין ומברך עליו לפני הסעודה \u0003\"בורא פרי הגפן\".\u0004 מסופר: \u0003רב אשי איקלע\u0004 \u0005[נזדמן]\u0006 לעיר \u0003מחוזא, אמרו ליה\u0004 \u0005[לו]\u0006 החכמים שם: \u0003ליקדיש לן מר קידושא רבה\u0004 \u0005[יקדש לנו אדוני\u0006 ביום השבת \u0005קידוש גדול]\u0006 ומיד אחר כך \u0003הבו ליה\u0004 \u0005[נתנו לו]\u0006 כוס יין.","והוא לא ידע למה הם מתכוונים כשהם אומרים \"קידושא רבה\" שמא מוסיפים הם דברים בקידוש היום, \u0003סבר: מאי ניהו \"קידושא רבה\"\u0004 \u0005[מה הוא זה קידוש גדול]\u0006 שהם אומרים? \u0003אמר\u0004 בלבו: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל הברכות כולן\u0004 הטעונות כוס — \u0003\"בורא פרי הגפן\" אמרי ברישא\u0004 \u0005[אומרים בתחילה],\u0006 ולכן \u0003אמר \"בורא פרי הגפן\" ואגיד ביה\u0004 \u0005[והאריך בו]\u0006 לחכות אם מצפים הם לברכה נוספת, \u0003חזייה לההוא סבא דגחין ושתי\u0004 \u0005[ראה לזקן אחד\u0006 שהיה שם \u0005שגוחן\u0006 על הכוס שלו \u0005ושותה]\u0006 והבין שזה סוף הברכה, \u0003קרי אנפשיה\u0004 \u0005[קרא על עצמו]\u0006 \u0003\"החכם עיניו בראשו\"\u0004 (קהלת ב, יד) שמתוך התבוננותו למד כיצד לנהוג.","הבאנו קודם לכן ש \u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003בני ר' חייא: מי שלא הבדיל במוצאי שבת — מבדיל והולך בכל השבת\u0004 (השבוע) \u0003כולו.\u0004 ושואלים: \u0003ועד כמה,\u0004 עד איזה יום בשבוע מבדיל, האם עד סוף השבוע? \u0003אמר ר' זירא: עד\u0004 יום \u0003רביעי בשבת\u0004 ומאז והלאה כבר אינו נחשב לשבוע זה.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דיתיב\u0004 \u0005[שישב]\u0006 \u0003ר' זירא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אסי\u0004 הוא שישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003לענין\u0004 נוסח כתיבת \u0003גיטין חדא בשבתא, תרי ותלתא — בתר שבתא\u0004 \u0005[יום ראשון בשבת, שני ושלישי\u0006 קרויים \u0005לאחר השבת]\u0006 ואם בנוסח הגט או בתנאי שבו מוגדר זמן כ\"אחר השבת\" — הכוונה היא לימים ראשון, שני או שלישי בשבוע. \u0003ארבע וחמשא ומעלי יומא — \"קמי שבתא\"\u0004 \u0005[רביעי וחמישי וערב יום\u0006 השבת, הם נקראים \u0005\"לפני השבת\"].\u0006 וכן הוא לענין הבדלה שימים אלו נחשבים עדיין כ\"אחר השבת\" וראויים להבדלה.","\u0003אמר ר' יעקב בר אידי: אבל\u0004 המבדיל בתוך ימות השבוע לא מברך \u0003על האור\u0004 (אש), שאין זה זמנו, שתיקנו ברכה זו רק במוצאי שבת, זמן בריאת האש.","\u0003אמר רב ברונא אמר רב:\u0004"],["\u0003הנוטל ידיו\u0004 לפני אכילת לחם \u0003לא יקדש\u0004 לאחר הנטילה, משום שהקידוש מפסיק בין נטילת ידים ואכילה, ויצטרך ליטול ידיו ולברך בשנית, אלא ישמע קידוש מאחר. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב יצחק בר שמואל בר מרתא: אכתי\u0004 \u0005[עדיין]\u0006 \u0003לא\u0004 עבר זמן מאז \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב\u0004 וכבר \u0003שכחנינהו לשמעתתיה\u0004 \u0005[שכחנו את הלכותיו].\u0006 \u0003זימנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים רבות הייתי עומד לפני]\u0006 \u0003רב,\u0004 ואז ראיתי כי \u0003זימנין דחביבא עליה ריפתא\u0004 \u0005[פעמים שחביבה\u0006 היתה \u0005עליו הפת] —\u0006 היה \u0003מקדש אריפתא\u0004 \u0005[על הפת]\u0006 והיה נוטל את ידיו תחילה ומקדש על הפת עצמה, ואוכל מיד. \u0003זימנין דחביבא ליה חמרא\u0004 \u0005[פעמים שחביב לו היין] —\u0006 היה \u0003מקדש אחמרא\u0004 \u0005[על היין].\u0006 ומכל מקום למדנו שהקידוש אינו נחשב כהפסקה בין נטילת ידים ואכילה.","\u0003אמר רב הונא אמר רב:\u0004 מי ש\u0003טעם\u0004 מזון כלשהו בליל שבת \u0003—\u0004 שוב \u0003אינו מקדש\u0004 בלילה, שאין קידוש אלא קודם האוכל ויקדש למחר קודם סעודת היום. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חנא בר חיננא מרב הונא: טעם\u0004 במוצאי שבת לפני הבדלה \u0003מהו שיבדיל? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני אומר טעם — מבדיל, ורב אסי אמר: טעם — אינו מבדיל.\u0004","מסופר: \u0003רב ירמיה בר אבא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבי\u0004 \u0005[לביתו]\u0006 של \u0003רב אסי, אישתלי וטעים מידי\u0004 \u0005[שכח וטעם משהו]\u0006 לפני הבדלה לאחר צאת השבת, \u0003הבו ליה כסא ואבדיל\u0004 \u0005[נתנו לו כוס\u0006 יין \u0005והבדיל].\u0006 לאחר מכן \u0003אמרה ליה דביתהו\u0004 \u0005[לו אשתו]\u0006 של רב אסי לבעלה: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003לא עביד הכי\u0004 \u0005[עושה כן]\u0006 כלומר, מנהגך שאם אתה טועם שוב אינך מבדיל! \u0003אמר לה: שבקיה, כרביה סבירא ליה\u0004 \u0005[הניחיהו, כרבו סבור הוא]\u0006 שהוא תלמידו של רב האומר שמי שטעם לפני הבדלה — מבדיל.","\u0003אמר רב יוסף אמר שמואל:\u0004 מי ש\u0003טעם\u0004 לפני קידוש — \u0003אינו מקדש,\u0004 ומי ש\u0003טעם\u0004 לפני הבדלה \u0003— אינו מבדיל. ורבה אמר\u0004 בשם \u0003רב נחמן אמר שמואל:\u0004 מי ש\u0003טעם\u0004 לפני קידוש \u0003— מקדש,\u0004 ומי ש\u0003טעם\u0004 לפני הבדלה \u0003— מבדיל.\u0004"],["\u0003אמר רבא: הילכתא\u0004 \u0005[הלכה]\u0006 היא: מי ש\u0003טעם\u0004 לפני קידוש \u0003— מקדש, ו\u0004מי ש\u0003טעם\u0004 לפני הבדלה \u0003— מבדיל, ומי שלא קידש בערב שבת — מקדש והולך כל היום\u0004 של שבת \u0003כולו עד מוצאי שבת. מי שלא הבדיל במוצאי שבת — מבדיל והולך כל השבת\u0004 (השבוע) \u0003כולו,\u0004 כלומר, כל חלק השבוע שעדיין נחשב כאחרי השבת, שזהו עד יום רביעי.","\u0003אמימר פתח לה להא שמעתא דרבא בהאי לישנא\u0004 \u0005[פתח\u0006 ושנה \u0005את השמועה,\u0006 ההלכה, \u0005הזו של רבא בלשון זו],\u0006 \u0003אמר רבא הילכתא\u0004 \u0005[הלכה]:\u0006 \u0003טעם\u0004 לפני קידוש \u0003— מקדש, טעם\u0004 לפני הבדלה — \u0003מבדיל, מי שלא קידש בערב שבת — מקדש והולך כל היום כולו, מי שלא הבדיל במוצאי שבת מבדיל והולך כל היום כולו\u0004 ביום ראשון ולא בכל השבוע.","מסופר: \u0003אמרי ליה מר ינוקא ומר קשישא בריה דרב חסדא\u0004 \u0005[אמרו לו מר הצעיר ומר הזקן בניו של רב חסדא]\u0006 \u0003לרב אשי: זימנא חדא איקלע\u0004 \u0005[פעם אחת הזדמן]\u0006 \u0003אמימר לאתרין\u0004 \u0005[למקומנו],\u0006 \u0003ולא הוה לן חמרא\u0004 \u0005[היה לנו יין]\u0006 להבדלה, \u0003אייתינא ליה שיכרא\u0004 \u0005[הבאנו לו שיכר]\u0006 \u0003ולא אבדיל\u0004 \u0005[הבדיל]\u0006 \u0003ובת טוות\u0004 \u0005[ולן בצום]\u0006 שהרי מי שלא הבדיל אסור לו לאכול. \u0003למחר טרחנא ואייתינא ליה חמרא, ואבדיל וטעים מידי\u0004 \u0005[למחרת טרחנו והבאנו לו יין, והבדיל וטעם דבר מה].\u0006 \u0003לשנה\u0004 אחרת \u0003תו איקלע לאתרין\u0004 \u0005[שוב הזדמן למקומנו],\u0006 \u0003לא הוה לן חמרא אייתינא שיכרא\u0004 \u0005[היה לנו יין הבאנו שכר]\u0006 \u0003אמר: אי הכי\u0004 \u0005[אם כך]\u0006 שאין יין מצוי במקומכם אלא בדוחק, הרי השיכר \u0003חמר\u0004 \u0005[יין]\u0006 \u0003מדינה הוא,\u0004 ודינו כיין במקום זה, \u0003אבדיל וטעים מידי\u0004 \u0005[הבדיל\u0006 עליו \u0005וטעם דבר].\u0006","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מהתנהגותו \u0005שלשה\u0006 דברים\u0005].\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]:\u0006 \u0003המבדיל בתפלה, צריך שיבדיל על הכוס.\u0004 שהרי מן הסתם כבר הבדיל אמימר בתפילתו באמירת \"אתה חוננתנו\". \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003אסור לו לאדם שיאכל קודם שיבדיל. ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003מי שלא הבדיל במוצאי שבת, מבדיל והולך כל השבת כולו.\u0004","אגב המעשה בסירובו של אמימר להבדיל על שיכר, דנים בשאלה זו בהרחבה. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב הונא מרב חסדא: מהו לקדושי אשיכרא\u0004 \u0005[לקדש על שיכר\u0006 תמרים\u0005]?\u0006 \u0003אמר: השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה פירזומא ותאיני ואסני\u0004 \u0005[שיכר שעורים ו\u0006שיכר \u0005תאנים ו\u0006שיכר \u0005תותים]\u0006 שהם מעולים בטעמם \u0003דבעאי מיניה\u0004 \u0005[ששאלתי ממנו]\u0006 \u0003מרב\u0004 אם מותר לקדש עליהם, \u0003ורב\u0004 שאל שאלה זו בזמנו \u0003מר' חייא, ור' חייא\u0004 שאל שאלה זו \u0003מרבי ולא פשט ליה\u0004 \u0005[פתר לו]\u0006 ולא מצא היתר ברור לדבר, אם כן \u0003שיכרא מיבעיא\u0004 \u0005[שיכר\u0006 תמרים \u0005צריך לומר]\u0006 שאין מקום להתירו לקידוש?!","\u0003סבור מינה\u0004 \u0005[סברו מכאן]\u0006 השומעים כי \u0003קדושי\u0004 \u0005[לקדש]\u0006 \u0003הוא\u0004 ש\u0003לא מקדשינן עילויה\u0004 \u0005[מקדשים עליו]\u0006 \u0003אבל אבדולי מבדלינן\u0004 \u0005[להבדיל מבדילים].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: כשם שאין מקדשין עליו\u0004 על שיכר תמרים \u0003כך אין מבדילין עליו. איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר רב תחליפא בר אבימי אמר שמואל:\u0004 שיכר, \u0003כשם שאין מקדשין עליו כך אין מבדילין עליו.\u0004","מסופר: \u0003לוי שדר ליה\u0004 \u0005[שלח לו]\u0006 \u0003לרבי שיכרא בר תליסר מגני\u0004 \u0005[שיכר בן שלוש עשרה שריות]\u0006 שבאותם מים שרה שלוש עשרה פעמים בזו אחר זו תמרים אחרים כדי שיספגו במים הליחה והטעם של כולם והוא מובחר ביותר, \u0003טעמיה\u0004 \u0005[טעם אותו]\u0006 רבי — \u0003הוה בסים טובא\u0004 \u0005[היה טוב ביותר],\u0006 \u0003אמר:\u0004 שיכר \u0003כגון זה ראוי לקדש עליו ולומר עליו כל שירות ותשבחות שבעולם\u0004 שהוא מובחר כיין. \u0003בליליא צעריה\u0004 \u0005[בלילה\u0006 לאחר מכן \u0005ציער אותו]\u0006 שגרם לו לבעיות עיכול. \u0003אמר: מיסרן ומפייס\u0004 \u0005[\u0006השיכר \u0005מצער\u0006 מצד אחד \u0005ומפייס\u0006 מצד שני\u0005].\u0006","כיון שהוזכר שהשיכר מצער בשל שתייתו מביאים עוד דברי אמוראים בנושא זה. \u0003אמר רב יוסף: אדור ברבים\u0004 נדר שאין לו התרה ש\u0003לא אישתי\u0004 \u0005[אשתה\u0006 עוד\u0005]\u0006 \u0003שיכרא\u0004 \u0005[שיכר]\u0006 מפני שהוא מזיק, אף שהיה משקה מקובל בבבל. \u0003אמר רבא: אישתי מי זוריון ולא אישתי שיכרא\u0004 \u0005[אשתה מי שריית\u0006 הפשתן \u0005ולא אשתה שיכר].\u0006","\u0003ואמר רבא: תיהוי שקיותיה שיכרא מאן דמקדש אשיכרא\u0004 \u0005[יהיה משקהו\u0006 הקבוע \u0005שיכר, של זה שמקדש על שיכר]\u0006 מידה כנגד מידה שכל מי ששותה שיכר לקידוש כדרך העניים - יהיה בסופו של דבר עני ויהיה משקהו הרגיל שיכר כדרך עניי בבל. מסופר: \u0003רב, אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רב הונא דקדיש אשיכרא\u0004 \u0005[ש\u0006הוא \u0005מקדש על שיכר],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שרי\u0004 \u0005[החל]\u0006 \u0003אבא\u0004 שמו הפרטי של רב \u0003למיקני איסתירי משיכרא\u0004 \u0005[לקנות מעות מן השיכר].\u0006 כלומר, התחלת לעסוק בתעשיית שיכר ומכירתו ומשום כך התחבב עליך השיכר, ומקדש אתה עליו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין מקדשין אלא על היין ואין מברכין אלא על היין.\u0004 ותוהים: \u0003אטו אשיכרא ואמיא מי לא מברכינן עליהו שהכל נהיה בדברו\u0004 \u0005[וכי על שיכר ועל מים אין אנו מברכין עליהם \"שהכל\"]?\u0006 \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה הכוונה: \u0003אין אומרים הבא כוס של ברכה לברך\u0004 ברכת המזון \u0003אלא על היין. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין מקדשין על השכר. משום\u0004 (בשם) \u0003ר' אלעזר בר ר' שמעון אמרו: מקדשין.\u0004","\u0003מטעימת יין\u0004 שאמרו שכל המקדש צריך שיטעום מן היין שבכוס הרי בטעימה \u0003כל שהוא\u0004 יוצא ידי קידוש. \u0003ר' יוסי בר יהודה אומר: מלא לוגמא\u0004 הוא שיעור הטעימה. \u0003אמר רב הונא אמר רב, וכן תני\u0004 \u0005[שנה]\u0006 \u0003רב גידל\u0004 ש\u0003מן\u0004 העיר \u0003נרש: המקדש וטעם\u0004 מן היין \u0003מלא לוגמא — יצא, ואם לאו\u0004 (לא) \u0003— לא יצא.\u0004","אמר \u0003רב נחמן בר יצחק\u0004 להעיר על כך: \u0003אנא תנינא לה\u0004 \u0005[אני שונה אותה]\u0006 את השמועה הזו בדיוק ואיני מזכיר בה \u0003לא גידול בר מנשיא ולא גידול בר מניומי אלא גידול סתמא\u0004 \u0005[סתם]\u0006 בלא כינוי לואי. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם קורא לו כך או כך? ומשיבים: \u0003למירמא דידיה אדידיה\u0004 \u0005[לסתור משלו על שלו].\u0006 כלומר, שאם יביאו דבר אחר מדבריו של חכם זה וירצו להראות סתירה בין הדברים, יש לדעת שלא אמר זאת בשמו של חכם מסויים, רב גידול זה או אחר, ואם תמצא סתירה — אפשר לומר שרב גידול אחר אמר זאת.","מעתה חוזרים אל המשנה. שנינו בה ש\u0003סמוך למנחה\u0004 בערב הפסח אסור לאכול. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003סמוך למנחה גדולה תנן\u0004 \u0005[שנינו]\u0006 שהוא כחצי שעה לאחר חצות היום \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003סמוך למנחה קטנה תנן\u0004 \u0005[שנינו]\u0006 שהוא כשעתיים וחצי לפני השקיעה.","ונברר את הצדדים בשאלה זו: \u0003סמוך למנחה גדולה תנן\u0004 \u0005[שנינו]\u0006 והטעם \u0003משום\u0004 קרבן ה\u0003פסח, דילמא אתי למימשך\u0004 \u0005[שמא יבוא להימשך]\u0006 ולהאריך בסעודה הרבה מאד, כדרך שהיו נוהגים בסעודות גדולות"],["\u0003ואתי לאימנועי מלמיעבד פסחא\u0004 \u0005[ויבוא להמנע מלעשות את הפסח],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003סמוך למנחה קטנה תנן\u0004 \u0005[שנינו]\u0006 וטעם האיסור \u0003משום מצה,\u0004 שאם יאכל סמוך ללילה \u0003דילמא אתי למיכלה למצה\u0004 \u0005[שמא יבוא לאכול את המצה]\u0006 \u0003אכילה גסה\u0004 כלומר אכילה שאדם אוכל בעל כורחו בלא רצון מתוך שהוא כבר שבע.","\u0003אמר רבינא: תא שמע\u0004 \u0005[בוא ושמע]\u0006 פיתרון לשאלה זו ממה ששנינו: \u0003אפילו אגריפס המלך שהוא רגיל לאכול\u0004 בכל יום \u0003בתשע שעות\u0004 (שלש שעות לפני הלילה) — \u0003אותו היום\u0004 של ערב פסח \u0003לא יאכל עד שתחשך.\u0004 ונדייק מכאן לעניננו: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003סמוך למנחה קטנה תנן\u0004 \u0005[שנינו],\u0006 \u0003היינו רבותיה\u0004 \u0005[זוהי גדולתו]\u0006 של \u0003אגריפס\u0004 שנמנע ואינו אוכל ונוהג איסור בעצמו לפני הזמן,","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003סמוך למנחה גדולה\u0004 שנינו, אם כן \u0003מאי רבותיה\u0004 \u0005[מהי גדולתו]\u0006 של \u0003אגריפס,\u0004 הלא \u0003חל איסור עליה מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני תשע שעות, שהרי מחצות היום ואילך אסור לו! \u0003אלא\u0004 על כורחך צריך לומר \u0003סמוך למנחה קטנה תנן\u0004 \u0005[שנינו],\u0006 ובכך גדולתו של אגריפס שנהג בערב פסח שלא כרגילותו.","ויש לשאול: \u0003סוף סוף מאי רבותיה\u0004 \u0005[מהי גדולתו]\u0006 של \u0003אגריפס, הא מטיא ליה\u0004 \u0005[הלא הגיע לו]\u0006 כבר \u0003זמן איסורא\u0004 \u0005[האיסור]\u0006 שהרי מן הסתם תימשך סעודתו מעט לתוך הזמן האסור לכל ישראל (שהרי זמן מנחה קטנה היא בתשע ומחצה), ומכיון שכך, אסור לו אף להתחיל לסעוד בשעה זו! ומשיבים: בכך יש חידוש, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003תשע שעות לאגריפס כארבע שעות דידן\u0004 \u0005[שלנו]\u0006 \u0003דמי\u0004 \u0005[נחשבות],\u0006 שכיון שאין הוא רגיל לסעוד סעודה ראשונה של יום בבוקר כשאר אנשים אלא אחר הצהרים, היה ראוי אולי לומר שמאחר וזוהי רגילותו, הרי שעה זו לגביו כשעת בוקר לשאר אנשים ויהיה רשאי לאכול בה אף בערב פסח, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מחלקים.","\u0003אמר ר' יוסי:\u0004 אף שאסור בסעודה ממש משעת המנחה ולמעלה, \u0003אבל מטביל\u0004 ואוכל \u0003הוא\u0004 במשך הזמן \u0003במיני תרגימא\u0004 \u0005[מטעמים,\u0006 פירות או בשר\u0005]\u0006 שאינם סעודה גמורה ואין בהם כדי שביעה. ומסופר: \u0003ר' יצחק מטביל בירקי\u0004 \u0005[בירקות]\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 תוספתא \u0005גם כן כך]\u0006 שמותר לאכול מיני תרגימא בערב פסח לאחר שעת המנחה: ערב פסח אחר הצהרים היה \u0003השמש מטביל בבני מעיין\u0004 של הבהמות שנשחטו לסעודת החג \u0003ונותנן לפני האורחים\u0004 המנויים על הפסח, כדי שאכילה זו תגרום להם לאכול בלילה את הפסח והמצה לתיאבון.","\u0003ואף על פי שאין ראיה\u0004 מפורשת מן הכתוב \u0003לדבר\u0004 שאכילה אחת מושכת אכילה אחרת, מכל מקום יש \u0003זכר\u0004 ורמז \u0003לדבר\u0004 מן הכתוב, \u0003שנאמר: \"נירו לכם ניר ואל תזרעו אל קצים\"\u0004 (ירמיהו ד, ג) ולומדים מכך שכדי להגיע לתוצאות צריך להשתדל ולהכין את הדברים מראש, וכן באכילה יש צורך לאכול משהו כדי שיוכל לאכול אחר כך הרבה.","מסופר: \u0003רבא הוה שתי חמרא כולי מעלי יומא דפסחא כי היכי דניגרריה לליביה דניכול מצה טפי לאורתא\u0004 \u0005[היה שותה יין כל ערב הפסח כדי שימשוך את לבו שיאכל מצה יותר בערב].\u0006 \u0003אמר רבא: מנא אמינא לה דחמרא מגרר גריר\u0004 \u0005[מנין אומר אני אותה\u0006 את הדעה הזו \u0005שהיין מושך\u0006 לאכול\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003בין הכוסות הללו\u0004 כגון בין כוס ראשון לשני \u0003אם רצה לשתות — ישתה,\u0004 שהוא מעורר תיאבון לסעודה, \u0003בין שלישי לרביעי\u0004 שהם לאחר המזון \u0003לא ישתה. ואי אמרת מסעד סעיד\u0004 \u0005[ואם אומר אתה\u0006 שהיין \u0005משביע],\u0006 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישתה\u0004 בין הכוסות הראשונות? \u0003הא קא אכיל\u0004 \u0005[הרי\u0006 ימצא \u0005שהוא אוכל]\u0006 את ה\u0003מצה אכילה גסה. אלא שמע מינה\u0004 \u0005[למד ממנה]:\u0006 שהיין \u0003מגרר גריר\u0004 \u0005[מושך\u0006 את התיאבון\u0005].\u0006","מסופר: \u0003רב ששת הוה יתיב בתעניתא כל מעלי יומא דפסחא\u0004 \u0005[היה יושב בתענית כל ערב יום הפסח].\u0006 ושואלים: \u0003נימא קסבר\u0004 \u0005[האם נאמר שסבר]\u0006 \u0003רב ששת\u0004 מה ששנינו \"סמוך למנחה\" — \u0003סמוך למנחה גדולה תנן\u0004 \u0005[שנינו]\u0006 והטעם הוא \u0003משום פסחא\u0004 \u0005[\u0006קרבן \u0005הפסח]\u0006 \u0003הוא, דילמא מימשך ואתי לאימנועי מלמעבד פיסחא\u0004 \u0005[שמא ימשך\u0006 בסעודה \u0005ויבוא להמנע מלעשות פסח]\u0006 \u0003הוא,\u0004","\u0003וסבר לה\u0004 \u0005[וסבר]\u0006 \u0003כי הא\u0004 \u0005[כ\u0006שיטה \u0005זו]\u0006 ש\u0003אמר ר' אושעיא אמר ר' אלעזר: מכשיר היה בן בתירא בפסח ששחטו שחרית בארבעה עשר\u0004 בניסן \u0003לשמו\u0004 כי לדעתו \u0003מצפרא זמן פסחא הוא, דכולי יומא חזי לפסחא\u0004 \u0005[שמהבוקר זמן\u0006 שחיטת \u0005הפסח הוא שכל היום ראוי ל\u0006שחיטת ה\u0005פסח]\u0006","ש\u0003סבר\u0004 שמה שנאמר בשחיטת הפסח \u0003\"בין הערבים\"\u0004 (שמות יב, ו), כוונתו \u0003בין ערב\u0004 של \u0003אתמול לערב דהאידנא\u0004 \u0005[של עכשיו]\u0006 בארבעה עשר, ונמצא שכל יום ארבעה עשר ראוי לשחיטת הפסח, ומצירוף שתי השיטות הללו נמנע רב ששת מלאכול כל ערב הפסח.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003לא,\u0004 אין צורך לומר כן, אלא \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב ששת דאיסתניס הוה\u0004 \u0005[שמפונק היה],\u0006 \u0003דאי טעים בצפרא מידי, לאורתא לא הוה מהני ליה מיכלא\u0004 \u0005[שאם היה טועם בבוקר דבר מה בערב לא היה נהנה עוד מהאוכל]\u0006 ולכן היה מתענה כל ערב הפסח, כדי שיאכל בערב את הפסח לתיאבון.","במשנה שנינו: \u0003ואפילו עני שבישראל לא יאכל עד שיסב, איתמר\u0004 \u0005[נאמר]\u0006 שדנו אמוראים בענין ההסיבה: \u0003מצה\u0004 לדעת הכל \u0003צריך הסיבה\u0004 בזמן אכילתה, באכילת \u0003מרור אין צריך הסיבה.\u0004 לענין \u0003יין, איתמר משמיה\u0004 \u0005[נאמר משמו]\u0006 של \u0003רב נחמן: צריך הסיבה. ואיתמר משמיה\u0004 \u0005[ונאמר משמו]\u0006 של \u0003רב נחמן: אין צריך הסיבה.\u0004","ומסבירים: \u0003ולא פליגי\u0004 \u0005[ולא נחלקו]\u0006 הדעות בעצם, כי \u0003הא בתרתי כסי קמאי הא בתרתי כסי בתראי\u0004 \u0005[זה בשתי כוסות ראשונות וזה בשתי כוסות אחרונות].\u0006 אלא שלמעשה לא נתברר הענין; \u0003אמרי לה להאי גיסא ואמרי לה להאי גיסא\u0004 \u0005[אמרו זאת לצד זה ואמרו זאת לצד זה]\u0006 ולא היה ברור באילו כוסות אמר רב נחמן שיש להסב ובאלו אמר שאין צריך להסב. ומסבירים: \u0003אמרי לה להאי גיסא\u0004 \u0005[אמרו אותו לצד זה]:\u0006 \u0003תרי כסי קמאי בעו הסיבה\u0004 \u0005[שתי הכוסות הראשונות צריכות הסבה],\u0006 כי \u0003השתא הוא דקא מתחלא לה חירות\u0004 \u0005[עכשיו הוא שמתחילה החירות],\u0006 שהרי מתחילים להזכיר את יציאת מצרים ושתייה מתוך הסיבה מורה על דרך חירות ואילו \u0003תרי כסי בתראי לא בעו הסיבה\u0004 \u0005[שתי כוסות אחרונות אינן צריכות הסיבה]\u0006 \u0003מאי דהוה — הוה\u0004 \u0005[מה שהיה היה]\u0006 וכבר קראו את ההגדה על הזכרת יציאת מצרים שבה ועכשיו אוכלים את סעודת החג.","\u0003ואמרי לה להאי גיסא\u0004 \u0005[ויש אומרים זאת לצד זה]:\u0006 \u0003אדרבה, תרי כסי בתראי בעו הסיבה, ההיא שעתא דקא הויא חירות\u0004 \u0005[שתי כוסות האחרונות צריכות הסיבה\u0006 כי \u0005בשעה זו היא שיש בה חירות],\u0006 \u0003תרי כסי קמאי לא בעו הסיבה\u0004 \u0005[שתי כוסות ראשונות אינן צריכות הסיבה]\u0006 \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003\"עבדים היינו\" קאמר\u0004 \u0005[אומר].\u0006 ומסכמים: \u0003השתא דאיתמר הכי ואיתמר הכי\u0004 \u0005[עכשיו שנאמר כך ונאמר כך]\u0006 ואין בידינו להכריע, \u0003אידי ואידי בעו\u0004 \u0005[אלו ואלו צריכות]\u0006 \u0003הסיבה.\u0004 ועוד בדיני הסבה.","\u0003פרקדן\u0004 (שכיבה על הגב) \u0003לא שמיה הסיבה\u0004 \u0005[אין שמו,\u0006 אינו נחשב, \u0005הסיבה]\u0006 \u0003הסיבת ימין\u0004 שנשען על צד זה \u0003לא שמה הסיבה\u0004 שאינה דרך חרות, שהרי אדם מיסב על צד שמאלו ומגיש את האוכל ביד ימין ולהפך קשה לו. \u0003ולא עוד אלא\u0004 אם יסב בצד ימין \u0003שמא יקדים קנה לוושט\u0004 ויכנס האוכל לתוך הקנה, מקום הנשימה \u0003ויבא לידי סכנה.\u0004","ועוד אמרו: \u0003אשה\u0004 העושה פסח \u0003אצל בעלה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003הסיבה,\u0004 אבל \u0003אם אשה חשובה היא\u0004 — אף היא \u0003צריכה הסיבה. בן אצל אביו בעי\u0004 \u0005[צריך]\u0006 \u0003הסיבה. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003תלמיד אצל רבו מאי\u0004 \u0005[מה\u0006 דינו\u0005]\u0006 שמא נאמר אנו שכיון שהתלמיד חייב במוראו של הרב אינו צריך הסיבה שהיא דרך חרות ואדנות גמורה?","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה לדבר ש\u0003אמר אביי: כי הוינן בי מר זגינן אבירכי דהדדי\u0004 \u0005[כאשר היינו\u0006 בפסח \u0005אצל אדוני,\u0006 רבה, \u0005היינו נשענים זה על ברכיו של זה]\u0006 שלא היו מקומות לכולם להסב והיו יוצאים כך ידי הסיבה, \u0003כי אתינן לבי\u0004 \u0005[כאשר באנו לבית]\u0006 \u0003רב יוסף אמר לן\u0004 \u0005[לנו]:\u0006 \u0003לא צריכתו\u0004 \u0005[צריכים אתם]\u0006 להסב, \u0003כי מורא רבך כמורא שמים\u0004 והתלמיד הוא כמשועבד לרבו ואינו יכול להראות לפניו דרך חירות.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003עם הכל אדם מיסב ואפילו תלמיד אצל רבו\u0004 וקשה לדברי רב יוסף! ומשיבים: \u0003כי תניא ההיא בשוליא דנגרי\u0004 \u0005[כאשר שנינו\u0006 ברייתא \u0005זו\u0006 הריהי \u0005בשוליית הנגרים]\u0006 לא בתלמיד הלומד אצל רבו תורה, אלא בלומד אצל רבו מלאכה. ותלמיד כזה אינו חייב במורא רבו, ואף הוא צריך הסיבה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 \u0003שמש מאי\u0004 \u0005[מה\u0006 דינו\u0005]\u0006 הצריך הוא הסיבה אם לא? ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון ממה ש\u0003אמר ר' יהושע בן לוי: השמש שאכל כזית מצה כשהוא מיסב — יצא.\u0004 ונדייק: \u0003מיסב — אין\u0004 \u0005[כן],\u0006 \u0003לא מיסב — לא, שמע מינה\u0004 \u0005[למד ממנה]:\u0006 כי \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003הסיבה,\u0004 ומסכמים: אכן, \u0003שמע מינה.\u0004","\u0003ואמר ר' יהושע בן לוי נשים חייבות בארבעה כוסות הללו\u0004 של פסח"],["משום \u0003שאף הן היו באותו הנס\u0004 של יציאת מצרים ולכן אף הן חייבות לשמוח בו.","\u0003אמר רב יהודה אמר שמואל: ארבעה כוסות הללו צריך שיהא בהן\u0004 יין חי \u0003כדי מזיגת כוס יפה\u0004 שלא היה נהוג לשתות יין חי, אלא היו נוהגים למוזגו במים ובדרך כלל בכמות של פי שלוש ממנו. אם \u0003שתאן חי\u0004 (יין שאינו מזוג) — \u0003יצא. שתאן בבת אחת\u0004 שמזג לפני שתייתו את כל ארבעת הכוסות לכוס אחת גדולה וממנה שתה בפעם אחת — \u0003יצא. השקה מהן לבניו ולבני ביתו — יצא.\u0004 ומבררים את הדינים הללו לפרטיהם.","נאמר בברייתא: \u0003שתאן\u0004 לארבע כוסות מיין \u0003חי — יצא. אמר רבא: ידי\u0004 חובת שתיית \u0003יין\u0004 שתיקנו חכמים ארבע כוסות — \u0003יצא,\u0004 אבל \u0003ידי חירות\u0004 לקיים שתייתו בדרך חירות, כיציאת מצרים, בשלמות — \u0003לא יצא,\u0004 שאין בן חורין ומפונק שותה יין חי.","עוד נאמר בברייתא: \u0003שתאן בבת אחת, רב אמר: ידי יין יצא\u0004 שקיים מצות שמחה ביום טוב אבל \u0003ידי ארבעה כוסות לא יצא,\u0004 שצריך לשתות ארבע כוסות כל אחת לעצמה. עוד נאמר בברייתא: \u0003השקה מהן לבניו ולבני ביתו — יצא, אמר רב נחמן בר יצחק: והוא דאשתי\u0004 \u0005[והוא ששתה\u0006 הוא עצמו\u0005]\u0006 \u0003רובא דכסא\u0004 \u0005[את רוב הכוס].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא על דברי רב יהודה: \u0003ארבעה כוסות הללו צריך שיהא בהן כדי רביעית, אחד\u0004 יין \u0003חי ואחד\u0004 יין \u0003מזוג, אחד\u0004 יין \u0003חדש ואחד\u0004 יין \u0003ישן. ר' יהודה אומר: צריך שיהא בו\u0004 גם \u0003טעם\u0004 גם \u0003מראה יין. קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ששיעור הכוסות הוא \u0003כדי רביעית, ואת אמרת\u0004 \u0005[ואתה אמרת]\u0006 \u0003כוס יפה\u0004 לכל אחד!","ומשיבים: \u0003אידי ואידי חד שיעורא הוא\u0004 \u0005[זה וזה שיעור אחד הוא],\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"כדי מזיגת כוס יפה\" דקאמר\u0004 \u0005[שאמר]\u0006 רב יהודה, הכוונה — \u0003לכל חד וחד\u0004 \u0005[לכל אחד ואחד]\u0006 מן הכוסות ואם כן \u0003הוי להו כולהו רביעית\u0004 \u0005[הרי הן כולן\u0006 יחד שיעור של \u0005רביעית\u0006 יין חי\u0005],\u0006 שהרי לפי נוהג המזיגה, רבע מתכולת הכוס היתה מיין חי ולפי חשבון זה סכום ארבע רביעיות כוס בת רביעית הלוג — הרי זה רביעית.","בברייתא שנינו עוד כי \u0003ר' יהודה אומר: צריך שיהא בו טעם ומראה. אמר רבא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל תרא יין כי יתאדם\"\u0004 (משלי כג, לא), הרי שביין יש חשיבות לא רק בטעם אלא גם במראה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הכל חייבין בארבעה כוסות הללו, אחד אנשים, ואחד נשים, ואחד תינוקות, אמר ר' יהודה: וכי מה תועלת יש לתינוקות ביין?\u0004 והא אינם נהנים ממנו! \u0003אלא מחלקין להן\u0004"],["\u0003קליות\u0004 (חיטים שנקלו באש) \u0003ואגוזין בערב פסח כדי שלא ישנו,\u0004 וגם כדי ש\u0003ישאלו\u0004 מה נשתנה הלילה הזה. \u0003אמרו עליו על ר' עקיבא שהיה מחלק קליות ואגוזין לתינוקות בערב פסח כדי שלא ישנו וישאלו. תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: חוטפין מצות בלילי פסחים\u0004 שאוכלים אותן במהירות וחטיפה \u0003בשביל תינוקות שלא ישנו\u0004 מתוך החידוש שבדבר ויתמהו וישאלו.","\u0003תניא\u0004 \u0005[שנינו\u0006 עוד בברייתא\u0005],\u0006 \u0003אמרו עליו על ר' עקיבא: מימיו לא אמר\u0004 לתלמידים \u0003הגיע עת לעמוד\u0004 ולהפסיק את הלימוד \u0003בבית המדרש\u0004 והיה ממשיך ככל שהיו מוכנים לשמוע, \u0003חוץ מערבי פסחים וערב יום הכפורים\u0004 שהיה מפסיק שיעורו. ומסבירים: ב\u0003ערב פסח בשביל\u0004 שיילכו \u0003התינוקות\u0004 לישון בצהרי היום, \u0003כדי שלא\u0004 יהיו עייפים ו\u0003ישנו\u0004 בלילה. \u0003וערב יום הכיפורים כדי\u0004 שיזכרו ו\u0003יאכילו את בניהם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חייב אדם לשמח בניו ובני ביתו ברגל, שנאמר: \"ושמחת בחגך\u0004 אתה ובנך ובתך... והיתום והאלמנה אשר בשעריך\u0003\"\u0004 (דברים טז, יד). \u0003במה משמחם? — ב\u0004שתיית \u0003יין.\u0004","\u0003ר' יהודה אומר:\u0004 כל אחד משמחו בדבר שהוא נהנה בו. \u0003אנשים\u0004 יש להנות אותם \u0003בראוי להם, ונשים\u0004 יש להנות אותן \u0003בראוי להן.\u0004 ומפרטים: \u0003אנשים\u0004 יש להנות אותם \u0003בראוי להם — ביין. ונשים במאי\u0004 \u0005[במה]?\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 משמחן לכבוד החג בבגד חדש שקונה להן, ש\u0003בבבל\u0004 קונה להן \u0003בגדי צבעונין,\u0004 ואילו \u0003בארץ ישראל\u0004 קונה להן ומשמחן \u0003בבגדי פשתן מגוהצין\u0004 שמייצרים בארץ.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה בן בתירא אומר: בזמן שבית המקדש קיים אין שמחה אלא\u0004 באכילת \u0003בשר\u0004 הקרבן, \u0003שנאמר: \"וזבחת שלמים ואכלת שם ושמחת לפני ה' אלהיך\"\u0004 (דברים כז, ז) \u0003ועכשיו שאין בית המקדש קיים\u0004 ואין אוכלים מן הקרבנות \u0003אין\u0004 קיום מצות \u0003שמחה אלא\u0004 בשתיית \u0003יין\u0004 בחג, \u0003שנאמר: \"ויין ישמח לבב אנוש\"\u0004 (תהילים קד, טו).","\u0003אמר ר' יצחק: קסתא דמוריסא דהוה בציפורי היא הות כמין לוגא דמקדשא\u0004 \u0005[כלי\u0006 שבו היו מודדין את \u0005המורייס שהיה בציפורי הוא היה כעין\u0006 שיעורו של ה\u0005לוג בבית המקדש]\u0006 \u0003ובה\u0004 היו \u0003משערין רביעית של פסח,\u0004 שהיו ממלאים אותה ולאחר מכן מחלקים את תוכנה לארבע כוסות והכמות שהיתה מכילה כל כוס הרי זו רביעית. והוא הדין גם לשאר רביעיות (שהן רבעי הלוג) המוזכרות בהלכה. \u0003אמר ר' יוחנן: תמנייתא קדמייתא דהוה בטבריא הות יתירה על דא ריבעא\u0004 \u0005[מידת השמינית הקדומה שהיתה בטבריא היתה יתירה על זאת\u0006 שאמרנו כדי \u0005רבע]\u0006 \u0003ובה משערין רביעית של פסח,\u0004 שהיו ממלאים אותה מים ומערים את תוכנה לתוך כלי מידה הנהוג עכשיו ולאחר שנתמלא זה, הרי מה שנותר בכלי ה\"תמנייתא\" — זוהי רביעית.","ובענין זה \u0003אמר רב חסדא:\u0004 מידת \u0003רביעית של תורה\u0004 היא הנפח של \u0003אצבעים על אצבעים ברום אצבעים וחצי אצבע וחומש אצבע. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין זה לגבי מקוה שבה נאמר: \u0003\"ורחץ במים את כל בשרו\"\u0004 (ויקרא טו, טז), ודרשו מכאן: \"כל בשרו\" — \u0003שלא יהא דבר חוצץ בין בשרו למים. \"במים\",\u0004 כלומר: המים המיוחדים ולא כל מים והם \u0003מי מקוה. \"את כל בשרו\" — מים\u0004 בשיעור \u0003שכל גופו עולה\u0004 (נכנס) \u0003בהן, וכמה הן?\u0004"],["\u0003אמה על אמה ברום שלש אמות, ושיערו חכמים\u0004 את נפח \u0003שיעור מי מקוה\u0004 זה שהוא בן \u0003ארבעים סאה.\u0004","אגב דברים אלו שנאמרו בענין מידות \u0003אמר רב אשי: אמר לי רבין בר חיננא: שולחן של מקדש\u0004 שעליו היו מניחים את לחם הפנים — \u0003של פרקים הוה\u0004 \u0005[היה]\u0006 ואפשר היה לפרקו לחלקים, \u0003דאי סלקא דעתך הדוקי הוה מיהדק\u0004 \u0005[שאם עולה בדעתך שמהודק היה\u0006 כחטיבה אחת\u0005],\u0006 הלא שולחן מידתו היתה אמתיים אורך על אמה רוחב על אמה וחצי גובה, ואם כן \u0003אמתא באמתא היכי מטבליה\u0004 \u0005[אמה\u0006 הרוחב של השולחן \u0005באמה\u0006 של בור המקוה \u0005היאך היה מטביל אותו]\u0006 שהרי את השולחן היו מטבילים מדי פעם בפעם כאשר נטמא, וכיצד אפשר להטבילו במקוה ששיעורה אמה על אמה?!","ומשיבים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 בכך? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003בים שעשה שלמה הוה מטביל ליה\u0004 \u0005[היה מטביל אותו]\u0006 שהוא מקוה רחב, כאמור: \"ויעש את הים מוצק עשר באמה משפתו עד שפתו עגול סביב\" (מלכים א' ז, כג) \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: ים שעשה שלמה מחזיק\u0004 בנפחו כמות מים של \u0003מאה וחמשים מקוה טהרה\u0004 ובודאי אפשר היה להטביל בו אפילו כלים גדולים יותר.","במשנה שנינו שאפילו עני מישראל \u0003לא יפחתו לו מארבעה\u0004 כוסות. ושואלים: \u0003היכי מתקני רבנן מידי דאתי בה לידי סכנה\u0004 \u0005[כיצד מתקנים חכמים דבר,\u0006 תקנה, \u0005שיבוא בה לידי סכנה]\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יאכל אדם תרי\u0004 \u0005[שתים]\u0006 (מאכל במנין זוגי) \u0003ולא ישתה תרי\u0004 \u0005[שתים,\u0006 זוגות\u0005]\u0006 \u0003ולא יקנח\u0004 עצמו ב\u0003תרי\u0004 \u0005[שתים,\u0006 זוגות\u0005]\u0006 \u0003ולא יעשה צרכיו\u0004 (תשמיש) \u0003תרי\u0004 \u0005[שתים,\u0006 זוגות\u0005],\u0006 כאשר יבואר שחששו מפני כשפים ומזיקים כשמשתמש בזוגות, ומדוע אם כן לא חששו חכמים לסכנת זוגות בתקנת ארבע כוסות אלה?","\u0003אמר רב נחמן: אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ליל שמרים\u0004 הוא לה'\u0003\"\u0004 (שמות יב, מב) ויש ללמוד מכך שהוא \u0003ליל המשומר ובא מן המזיקין\u0004 מכל הסוגים ולכן אין לחשוש לנזק בלילה זה.","\u0003רבא אמר: כוס של ברכה\u0004 שמברכים על המזון בליל פסח יש בה גם מצוה נוספת שאינו רק לענין חירות והוא \u0003מצטרף לטובה\u0004 למצוות ארבע כוסות \u0003ואינו מצטרף לרעה\u0004 ולענין זוגות ניתן לחשוב כאילו יש רק שלש כוסות בלבד. \u0003רבינא אמר: ארבעה כסי תקינו רבנן\u0004 \u0005[ארבע כוסות\u0006 נבדלות \u0005תקנו חכמים]\u0006 ושותה אותן \u0003דרך חירות\u0004 ואינו מתחשב במה שיקרה אחר כך ולכן \u0003כל חד וחד\u0004 \u0005[כל אחד ואחד]\u0006"]]};
